INSERT INTO _n1_b10_guard_0125(ok) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM japanese_jlpt_daily_sessions s JOIN japanese_jlpt_study_plans p ON p.id=s.plan_id WHERE p.plan_code='N1_2027_JUL' AND s.study_date BETWEEN '2027-02-04' AND '2027-02-17' AND (s.status <> 'not_started' OR s.started_at IS NOT NULL OR s.completed_at IS NOT NULL)) THEN 1 ELSE 0 END;
INSERT INTO _n1_b10_words_0125(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3841','2027-02-04','歯科','しか','치과; 치의학','歯・歯ぐき・口腔などを診療する医学分野、またはその診療科。','定期検診のため、半年に一度は歯科を受診するようにしている。','정기검진을 위해 반년에 한 번은 치과를 방문하려고 한다.'),
('n1-3842','2027-02-04','公立','こうりつ','공립; 지방자치단체가 설립·운영함','地方公共団体などが設立・運営すること。また、その学校・施設。','この地域では公立病院が救急医療の中心的な役割を担っている。','이 지역에서는 공립병원이 응급의료의 중심 역할을 맡고 있다.'),
('n1-3843','2027-02-04','登校','とうこう','등교; 학교에 감','児童・生徒などが学校へ行くこと。','大雪のため、午前中は登校を見合わせるよう学校から連絡があった。','폭설 때문에 오전에는 등교를 보류하라는 연락이 학교에서 왔다.'),
('n1-3844','2027-02-04','入浴','にゅうよく','입욕; 목욕함','風呂・浴槽などに入って身体を洗ったり温めたりすること。','高齢者が入浴する際は、急な温度変化に十分注意する必要がある。','고령자가 목욕할 때는 급격한 온도 변화에 충분히 주의할 필요가 있다.'),
('n1-3845','2027-02-04','聖書','せいしょ','성경; 성서','キリスト教において信仰と教えの基礎となる聖典。','彼は宗教史を研究するため、複数の言語で聖書を読み比べている。','그는 종교사를 연구하기 위해 여러 언어로 된 성경을 비교해 읽고 있다.'),
('n1-3846','2027-02-04','黄色','おうしょく','황색; 노란색','黄の色。日常語では『きいろ』が一般的で、『おうしょく』は複合語や文章語でも用いられる。','注意が必要な箇所は黄色で表示し、重大な警告は赤色で示している。','주의가 필요한 부분은 황색으로 표시하고 중대한 경고는 빨간색으로 나타내고 있다.'),
('n1-3847','2027-02-04','相対','あいたい','당사자끼리 직접; 대면; 중개 없이','第三者を介さず、当事者同士が直接向かい合って物事を行うこと。『そうたい』とは意味・読みが異なる。','仲介業者を通さず、売り手と買い手が相対で条件を決める取引もある。','중개업자를 통하지 않고 판매자와 구매자가 당사자끼리 직접 조건을 정하는 거래도 있다.'),
('n1-3848','2027-02-04','明白','あからさま','노골적; 공공연함; 숨김없음','隠そうとせず、はっきり表に出しているさま。露骨。','彼はあからさまに不満そうな表情を見せた。','그는 노골적으로 불만스러운 표정을 보였다.'),
('n1-3849','2027-02-04','訪れる','おとずれる','방문하다; 찾아오다','人・場所を訪問する。また、季節・機会・状態などがやって来る。','長い不況を経て、地域経済にもようやく回復の兆しが訪れた。','오랜 불황을 거쳐 지역 경제에도 마침내 회복의 조짐이 찾아왔다.'),
('n1-3850','2027-02-04','決まる','きまる','정해지다; 결정되다','予定・方針・結果などが確定する。また、服装・技などがうまく決まる。','新しい担当者が決まり次第、関係部署に連絡します。','새 담당자가 결정되는 대로 관계 부서에 연락하겠습니다.'),
('n1-3851','2027-02-04','楽しむ','たのしむ','즐기다; 감상하다','物事から喜び・面白さを感じ、味わう。','旅行では有名な観光地だけでなく、地域の日常文化も楽しみたい。','여행에서는 유명 관광지뿐 아니라 지역의 일상 문화도 즐기고 싶다.'),
('n1-3852','2027-02-04','返る','かえる','돌아가다; 되돌아오다; 원상태가 되다','ある状態・場所などが元に戻る。また、反応・結果が自分の側へ戻る。','質問を具体的にすると、より明確な答えが返ってくる。','질문을 구체적으로 하면 더 명확한 답이 돌아온다.'),
('n1-3853','2027-02-04','集まる','あつまる','모이다; 집중되다','人・物・情報・関心などが一つの場所・対象に寄る。','新しい研究計画には国内外から多くの専門家が集まった。','새 연구 계획에는 국내외에서 많은 전문가가 모였다.'),
('n1-3854','2027-02-04','済ます','すます','끝내다; 마치다; 간단히 때우다','するべきことを終える。また、必要なことを簡単な方法で間に合わせる。','午前中に用事を済ませ、午後は家で休むことにした。','오전에 볼일을 마치고 오후에는 집에서 쉬기로 했다.'),
('n1-3855','2027-02-04','突く','つつく','콕콕 찌르다; 쪼다; 건드리다','指・くちばし・細い物などで、軽く何度も押したり刺したりする。','鳥が地面をくちばしでつついて餌を探している。','새가 땅을 부리로 쪼며 먹이를 찾고 있다.'),
('n1-3856','2027-02-04','潜る','くぐる','아래를 빠져나가다; 통과하다; 헤쳐 나가다','門・橋・障害物などの下や間を通り抜ける。また、困難・危険な状況を経験しながら切り抜ける。','低い門をくぐると、静かな庭が広がっていた。','낮은 문 아래를 지나가자 조용한 정원이 펼쳐졌다.'),
('n1-3857','2027-02-04','垂れる','たれる','늘어지다; 드리워지다; 떨어지다','物の一部が下向きに長く下がる。また、液体が上から下へ少しずつ落ちる。','雨にぬれた枝が重みで道路側へ垂れている。','비에 젖은 가지가 무게 때문에 도로 쪽으로 늘어져 있다.'),
('n1-3858','2027-02-04','遥か','はるか','아득히; 훨씬; 멀리','距離・時間・程度などが非常に遠い、または大きく隔たっているさま。','当初の予想をはるかに上回る応募があり、受付を早めに締め切った。','당초 예상을 훨씬 웃도는 지원이 있어 접수를 일찍 마감했다.'),
('n1-3859','2027-02-04','切り替える','きりかえる','전환하다; 바꾸다','それまでの状態・方法・考えなどを別のものに変える。','問題が起きたので、すぐに予備回線へ切り替えた。','문제가 생겨 즉시 예비 회선으로 전환했다.'),
('n1-3860','2027-02-04','果てる','はてる','끝나다; 다하다; 죽다','物事が終わる。力などが尽きる。また、命が終わる。','長い旅の途中で力が果てそうになった。','긴 여행 도중 힘이 다할 것 같았다.'),
('n1-3861','2027-02-05','上下','うえした','위아래; 상하','上と下。また、上下の方向や、立場の上の者と下の者。『じょうげ』とも読む。','画面を上下にスクロールすると、すべての項目を確認できる。','화면을 위아래로 스크롤하면 모든 항목을 확인할 수 있다.'),
('n1-3862','2027-02-05','体','てい','모양; 태; 상태; 체재','外から見た様子・ありさま・形。『～の体』の形でも使う。','彼は疲れ切った体で椅子に座り込んだ。','그는 완전히 지친 모습으로 의자에 주저앉았다.'),
('n1-3863','2027-02-05','暇','いとま','틈; 여가; 휴가; 작별','自由に使える時間。また、休暇・別れを表す古風な語。','忙しくて本を読む暇もない。','바빠서 책 읽을 틈도 없다.'),
('n1-3864','2027-02-05','値','あたい','값; 가치; 수치','物の価格・価値。また、数学・計算などで得られる数値。','測定した値が基準を大きく超えたため、装置を停止して原因を調べた。','측정값이 기준을 크게 초과해 장치를 정지하고 원인을 조사했다.'),
('n1-3865','2027-02-05','暦','こよみ','달력; 역법','日・月・季節・行事などを一定の方式で記したもの。カレンダー。','暦の上では春だが、山間部ではまだ雪が残っている。','달력상으로는 봄이지만 산간 지역에는 아직 눈이 남아 있다.'),
('n1-3866','2027-02-05','格','かく','격; 품격; 지위·등급','人・物の地位・等級・品位などを表す。','歴史あるホテルとしての格を保つため、接客の質にも厳しい基準を設けている。','역사 있는 호텔로서의 격을 유지하기 위해 접객 품질에도 엄격한 기준을 두고 있다.'),
('n1-3867','2027-02-05','渦','うず','소용돌이; 소용돌이치는 상태','水・空気などが回転しながら中心へ巻き込むように動く状態。また、比喩的に激しい動きや混乱の中心。','川の曲がり角に大きな渦ができていた。','강의 굽이진 곳에 큰 소용돌이가 생겨 있었다.'),
('n1-3868','2027-02-05','仕立てる','したてる','짓다; 만들다; 재단하다; 길러내다','衣服などを作り上げる。また、人を教育して一人前に育てたり、ある目的に合うよう準備したりする。','この布で夏用のスーツを仕立ててもらった。','이 천으로 여름용 정장을 맞춰 만들었다.'),
('n1-3869','2027-02-05','鍛える','きたえる','단련하다; 훈련하다; 담금질하다','訓練して心身・能力を強くする。また、金属を打って強くする。','毎朝走って体を鍛えている。','매일 아침 달리며 몸을 단련하고 있다.'),
('n1-3870','2027-02-05','追い出す','おいだす','쫓아내다; 몰아내다; 축출하다','人・動物などをその場所・集団から強制的に外へ出す。','店員は迷惑行為を続ける客を店から追い出した。','점원은 민폐 행동을 계속하는 손님을 가게에서 내쫓았다.'),
('n1-3871','2027-02-05','埋まる','うずまる','파묻히다; 가득 차다','物に覆われて見えなくなる。また、周囲が物でいっぱいになる。','道が落ち葉で埋まっていた。','길이 낙엽에 파묻혀 있었다.'),
('n1-3872','2027-02-05','早める','はやめる','앞당기다; 빨리하다','予定・時刻などをより早くする。','台風のため出発時間を一時間早めた。','태풍 때문에 출발 시간을 한 시간 앞당겼다.'),
('n1-3873','2027-02-05','痛める','いためる','다치게 하다; 상하게 하다; 괴롭게 하다','体・心などを傷つけ、痛みや苦しみを与える。','重い荷物を持って腰を痛めた。','무거운 짐을 들다가 허리를 다쳤다.'),
('n1-3874','2027-02-05','取り寄せる','とりよせる','주문해서 받아오다; 다른 곳에서 가져오게 하다','品物・資料などを注文したり依頼したりして、別の場所から手元に届けさせる。','店に在庫がなかったので、別の支店から商品を取り寄せてもらった。','가게에 재고가 없어서 다른 지점에서 상품을 주문해 받아오게 했다.'),
('n1-3875','2027-02-05','丸める','まるめる','둥글게 만들다; 말다; 뭉치다; 구슬리다','物を丸い形にする、巻く。また、言葉巧みに人を自分の思い通りにする。','紙を丸めてごみ箱に捨てた。','종이를 둥글게 구겨 쓰레기통에 버렸다.'),
('n1-3876','2027-02-05','問い合わせる','といあわせる','문의하다; 조회하다; 확인을 요청하다','分からないことや確認したいことを、関係する相手・機関などに尋ねる。','詳しい料金については担当窓口に問い合わせてください。','자세한 요금은 담당 창구에 문의해 주세요.'),
('n1-3877','2027-02-05','弱る','よわる','약해지다; 쇠약해지다; 곤란해하다','体力・気力・勢いなどが弱くなる。また、困ってどうしたらよいか分からなくなる。','暑さが続いて、庭の植物もすっかり弱っている。','더위가 계속되어 정원의 식물도 완전히 약해져 있다.'),
('n1-3878','2027-02-05','眩しい','まぶしい','눈부시다; 빛나고 찬란하다','光が強すぎて目を開けていにくい。また、比喩的に非常に輝かしく感じる。','朝日が眩しくて、思わず目を細めた。','아침 햇살이 눈부셔서 나도 모르게 눈을 가늘게 떴다.'),
('n1-3879','2027-02-05','甘える','あまえる','응석부리다; 어리광부리다; 남의 호의에 기대다','相手の愛情・親切を頼りに、わがままに振る舞ったり遠慮なく頼ったりする。','いつまでも親に甘えてばかりはいられない。','언제까지나 부모에게 의지하며 응석만 부릴 수는 없다.'),
('n1-3880','2027-02-05','投げ出す','なげだす','내던지다; 팽개치다; 중도에 포기하다; 희생하다','物を放り出す。また、仕事・責任などを途中で放棄する。さらに、命・財産などを惜しまず差し出す。','難しいからといって、途中で仕事を投げ出してはいけない。','어렵다고 해서 도중에 일을 팽개쳐서는 안 된다.');
INSERT INTO _n1_b10_words_0125(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3881','2027-02-06','災害','さいがい','재해; 재난','地震・台風・洪水・火災などによって生じる大きな被害。','災害に備えて、各家庭で飲料水と食料を備蓄することが推奨されている。','재해에 대비해 각 가정에서 식수와 식량을 비축하는 것이 권장된다.'),
('n1-3882','2027-02-06','癌','がん','암; 암종','異常な細胞が増殖し、周囲の組織に広がる悪性腫瘍。','早期に癌を発見するため、定期的に検診を受けている。','암을 조기에 발견하기 위해 정기적으로 검진을 받고 있다.'),
('n1-3883','2027-02-06','脈','みゃく','맥; 맥박; 가능성의 실마리','心臓の動きに伴う脈拍。また、筋状につながるものや可能性のつながり。','医師が患者の脈を取った。','의사가 환자의 맥박을 짚었다.'),
('n1-3884','2027-02-06','宛','あて','~앞; 수신처; 대상','手紙・荷物などの送り先や相手を表す語。','この書類は人事部長宛に送ってください。','이 서류는 인사부장 앞으로 보내 주세요.'),
('n1-3885','2027-02-06','上手','うわて','한 수 위; 더 능숙한 사람; 고수','相手より技能・知恵などが優れていること。また、その人。','交渉では相手のほうが一枚上手だった。','협상에서는 상대가 한 수 위였다.'),
('n1-3886','2027-02-06','慣れ','なれ','익숙함; 숙련; 경험','繰り返し経験することで、物事に不安や不自由を感じなくなること。経験による習熟。','新しい作業は難しく感じるが、慣れれば短時間で処理できるようになる。','새 작업은 어렵게 느껴지지만 익숙해지면 짧은 시간에 처리할 수 있게 된다.'),
('n1-3887','2027-02-06','詳細','しょうさい','상세; 자세한 내용','細かい点まで詳しいこと。また、その内容。','変更内容の詳細は、後日ウェブサイトで公表される予定だ。','변경 내용의 상세 사항은 추후 웹사이트에 공개될 예정이다.'),
('n1-3888','2027-02-06','抜かす','ぬかす','빼먹다; 생략하다; 건너뛰다','順序の途中を飛ばす。また、言葉・項目などを省く。','大事な説明を一つ抜かして話してしまった。','중요한 설명 하나를 빼먹고 말해 버렸다.'),
('n1-3889','2027-02-06','当てはめる','あてはめる','적용하다; 맞춰 보다; 대입하다','ある基準・規則・型などを具体的な事例に適用する。','この公式に数値を当てはめて計算する。','이 공식에 수치를 대입해 계산한다.'),
('n1-3890','2027-02-06','粘る','ねばる','끈적거리다; 버티다; 끈기 있게 계속하다','粘り気がある。また、簡単にあきらめず最後まで続ける。','最後まで粘って、ようやく同点に追いついた。','끝까지 버텨 마침내 동점까지 따라잡았다.'),
('n1-3891','2027-02-06','短気','たんき','성급함; 다혈질','我慢する時間が短く、すぐ怒ったり結論を急いだりする性質。','短気を起こして判断すると、かえって問題を大きくすることがある。','성급하게 판단하면 오히려 문제를 키울 수 있다.'),
('n1-3892','2027-02-06','合唱','がっしょう','합창; 여러 사람이 함께 노래함','複数の人が声を合わせ、同じ曲または複数の声部を同時に歌うこと。','卒業式では生徒全員が校歌を合唱し、会場から大きな拍手が起こった。','졸업식에서는 전 학생이 교가를 합창해 행사장에서 큰 박수가 나왔다.'),
('n1-3893','2027-02-06','楽譜','がくふ','악보','音の高さ・長さ・強さなどを音符や記号で記したもの。','初めて見る楽譜でも、基本的な記号を理解していれば演奏の流れをつかめる。','처음 보는 악보라도 기본 기호를 이해하면 연주의 흐름을 파악할 수 있다.'),
('n1-3894','2027-02-06','衣類','いるい','의류; 옷가지','上着・シャツ・ズボンなど、身につける服の総称。','避難所には食料だけでなく、毛布や衣類などの生活物資も届けられた。','대피소에는 식량뿐 아니라 담요와 의류 같은 생활 물자도 전달되었다.'),
('n1-3895','2027-02-06','小銭','こぜに','잔돈; 동전','額の小さい硬貨や、細かく使える少額の金。','自動販売機で使うために、小銭を少し用意しておいた。','자동판매기에서 쓰려고 잔돈을 조금 준비해 두었다.'),
('n1-3896','2027-02-06','利子','りし','이자','金銭を貸し借りした際に、元金に対して一定の割合で支払われる金銭。','この預金は利子が低い代わりに、いつでも引き出すことができる。','이 예금은 이자가 낮은 대신 언제든 인출할 수 있다.'),
('n1-3897','2027-02-06','月日','がっぴ','월일; 날짜','月と日。特に年月日のうち、月と日の部分。','申請書には生年月日を数字で正確に記入してください。','신청서에는 생년월일을 숫자로 정확히 기입해 주세요.'),
('n1-3898','2027-02-06','満月','まんげつ','보름달; 만월','地球から見て、ほぼ完全な円形に見える月。','雲が晴れると、山の上に大きな満月が見えた。','구름이 걷히자 산 위로 큰 보름달이 보였다.'),
('n1-3899','2027-02-06','年長','ねんちょう','연장; 나이가 더 많음','年齢が上であること。また、集団の中で年上である人。','年長の社員が若手の相談役を務める制度が導入された。','연장자인 직원이 젊은 직원의 상담 역할을 맡는 제도가 도입되었다.'),
('n1-3900','2027-02-06','年頃','としごろ','나이대; 그럴 나이','ある特徴・行動が見られるようになる年齢や時期。特に、若者が成長していく時期。','子どもも自分の意見を強く持つ年頃になり、親子で話し合う機会が増えた。','아이도 자기 의견을 강하게 가지는 나이가 되어 부모와 대화할 기회가 늘었다.'),
('n1-3901','2027-02-07','一息','ひといき','한숨; 잠깐의 휴식; 한 번에','一度の呼吸。また、少し休むこと。さらに、途中で止まらず一気に行うことを表す。','作業が一段落したので、ここで一息入れてから次の工程に進もう。','작업이 일단락됐으니 여기서 잠깐 쉬고 다음 공정으로 넘어가자.'),
('n1-3902','2027-02-07','神殿','しんでん','신전','神を祭り、礼拝・儀式などを行うための建物。','遺跡からは古代の神殿とみられる石造建築の跡が発見された。','유적에서 고대 신전으로 보이는 석조 건축 흔적이 발견되었다.'),
('n1-3903','2027-02-07','音色','ねいろ','음색','声・楽器などが持つ、音の質や独特の響き。','同じ曲でも楽器が違えば、音色によって印象が大きく変わる。','같은 곡이라도 악기가 다르면 음색에 따라 인상이 크게 달라진다.'),
('n1-3904','2027-02-07','台本','だいほん','대본; 각본','演劇・映画・番組などで、せりふや動作・進行を書いたもの。','出演者は本番前に台本を読み合わせ、せりふのタイミングを確認した。','출연자들은 본방송 전에 대본을 맞춰 읽으며 대사 타이밍을 확인했다.'),
('n1-3905','2027-02-07','父母','ちちはは','부모; 아버지와 어머니','父と母。両親。','彼は幼い頃から父母の仕事を手伝いながら育った。','그는 어릴 때부터 부모의 일을 도우며 자랐다.'),
('n1-3906','2027-02-07','問屋','といや','도매상; 도매점','商品を仕入れて小売業者などに販売する卸売業者・卸売店。','この地域には昔から織物を扱う問屋が多かった。','이 지역에는 예전부터 직물을 취급하는 도매상이 많았다.'),
('n1-3907','2027-02-07','連休','れんきゅう','연휴','休日が二日以上続くこと。また、その続いた休日。','大型連休には高速道路や観光地の混雑が予想される。','긴 연휴에는 고속도로와 관광지의 혼잡이 예상된다.'),
('n1-3908','2027-02-07','晴天','せいてん','맑은 날씨; 청명한 하늘','雲が少なく、よく晴れた天気。','大会当日は晴天に恵まれ、予定どおりすべての競技が行われた。','대회 당일은 맑은 날씨를 만나 예정대로 모든 경기가 진행되었다.'),
('n1-3909','2027-02-07','期末','きまつ','기말; 기간의 끝','一定の期間・学期・会計年度などの終わり。','期末試験の結果は来週オンラインで発表される。','기말시험 결과는 다음 주 온라인으로 발표된다.'),
('n1-3910','2027-02-07','給食','きゅうしょく','급식','学校・施設などで、一定の人に食事を提供すること。また、その食事。','学校では栄養バランスを考えた給食が毎日提供されている。','학교에서는 영양 균형을 고려한 급식이 매일 제공되고 있다.'),
('n1-3911','2027-02-07','学芸','がくげい','학예; 학문과 예술','学問と芸術。また、それらに関する知識・技能。','博物館の学芸員は展示資料の調査や保存にも携わっている。','박물관 학예사는 전시 자료 조사와 보존에도 관여하고 있다.'),
('n1-3912','2027-02-07','劇団','げきだん','극단','演劇を継続的に制作・上演する人々の団体。','その劇団は地方を巡回しながら新作を上演している。','그 극단은 지방을 순회하며 신작을 공연하고 있다.'),
('n1-3913','2027-02-07','喜劇','きげき','희극; 코미디','笑いを中心に、人間や社会を明るく・風刺的に描く演劇・作品。','この作品は一見軽い喜劇だが、社会への鋭い批判も含んでいる。','이 작품은 겉보기에는 가벼운 희극이지만 사회에 대한 날카로운 비판도 담고 있다.'),
('n1-3914','2027-02-07','本館','ほんかん','본관; 주 건물','複数の建物のうち、中心となる主要な建物。','受付は別館ではなく本館の一階にあります。','접수처는 별관이 아니라 본관 1층에 있습니다.'),
('n1-3915','2027-02-07','下痢','げり','설사','腸の働きが乱れ、水分の多い便を何度も排出する症状。','下痢が続く場合は脱水を防ぐため、水分を十分に取る必要がある。','설사가 계속되면 탈수를 막기 위해 수분을 충분히 섭취해야 한다.'),
('n1-3916','2027-02-07','定食','ていしょく','정식; 세트 식사','主食・汁物・おかずなどを一定の組み合わせと価格で提供する食事。','昼は近くの食堂で焼き魚定食を注文した。','점심에는 근처 식당에서 생선구이 정식을 주문했다.'),
('n1-3917','2027-02-07','役場','やくば','관공서; 읍·면·촌사무소','町・村などの地方自治体の行政事務を行う役所。','住民票を取るため、午前中に町役場へ行った。','주민표를 발급받기 위해 오전에 정사무소에 갔다.'),
('n1-3918','2027-02-07','利息','りそく','이자','金銭を貸し借りした際に、元金に加えて支払われる金銭。','返済期間が長くなるほど、支払う利息の総額も増える。','상환 기간이 길어질수록 지불하는 이자의 총액도 늘어난다.'),
('n1-3919','2027-02-07','現像','げんぞう','현상; 사진 필름을 처리해 상을 나타냄','撮影したフィルム・感光材料などを薬品で処理し、記録された像を見える形にすること。','昔は撮影したフィルムを写真店へ持ち込み、現像を頼んでいた。','예전에는 촬영한 필름을 사진관에 가져가 현상을 맡기곤 했다.'),
('n1-3920','2027-02-07','星座','せいざ','별자리; 성좌','夜空の星を一定の形に結び付け、人物・動物などの名を付けた区分。','冬の夜空ではオリオン座などの明るい星座を見つけやすい。','겨울 밤하늘에서는 오리온자리 같은 밝은 별자리를 찾기 쉽다.');
INSERT INTO _n1_b10_words_0125(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3921','2027-02-08','母校','ぼこう','모교','自分が以前通い、特に卒業した学校。','卒業後十年ぶりに母校を訪れ、恩師と再会した。','졸업 후 10년 만에 모교를 찾아 은사와 다시 만났다.'),
('n1-3922','2027-02-08','本場','ほんば','본고장; 그 분야의 중심지','ある産物・技術・文化などが本来盛んで、中心となっている土地。','本場の料理を味わうために、休暇を利用して現地を訪れた。','본고장의 요리를 맛보기 위해 휴가를 이용해 현지를 찾았다.'),
('n1-3923','2027-02-08','主食','しゅしょく','주식; 주식품','日常の食事で中心となる食べ物。','地域によって米やパンなど主食となる食品は異なる。','지역에 따라 쌀이나 빵 등 주식이 되는 식품은 다르다.'),
('n1-3924','2027-02-08','女史','じょし','여사; 저명한 여성에 대한 경칭','社会的に活躍している女性を敬って呼ぶ語。現代ではやや古風な表現。','その評論では、近代文学に大きな影響を与えた作家を『○○女史』と紹介している。','그 평론에서는 근대 문학에 큰 영향을 준 작가를 ‘○○ 여사’라고 소개한다.'),
('n1-3925','2027-02-08','未婚','みこん','미혼','まだ結婚していないこと。','この調査では未婚者の割合も調べている。','이 조사에서는 미혼자의 비율도 조사하고 있다.'),
('n1-3926','2027-02-08','洋風','ようふう','서양풍; 서양식','西洋の様式・雰囲気を取り入れたさま。','古い家を洋風に改装した。','오래된 집을 서양식으로 개조했다.'),
('n1-3927','2027-02-08','大事','おおごと','큰일; 중대한 일','非常に重大で、簡単には済まない事態・出来事。','小さなミスだと思っていたが、後で大事になった。','작은 실수라고 생각했는데 나중에 큰일이 되었다.'),
('n1-3928','2027-02-08','流行','はやり','유행; 유행하는 것','ある時期に広く人気を集めたり、世間に広まったりすること。','今年はこの色が流行らしい。','올해는 이 색이 유행인 것 같다.'),
('n1-3929','2027-02-08','一見','いちげん','초면; 처음 방문함; 낯선 손님','その人や店などと初めて顔を合わせること。また、初めて訪れる客。','その店は一見の客でも丁寧に迎えてくれた。','그 가게는 처음 온 손님도 친절하게 맞아 주었다.'),
('n1-3930','2027-02-08','一目','いちもく','한눈; 한번 봄; 일견','一度見ること。ひと目。','その作品を一目見て、強く心を引かれた。','그 작품을 한눈에 보고 강하게 마음이 끌렸다.'),
('n1-3931','2027-02-08','作物','さくぶつ','작품; 저작물','文学・芸術などで作られた作品。','この作家の初期の作物には、後年の作風の特徴がすでに見られる。','이 작가의 초기 작품에는 훗날 작품 세계의 특징이 이미 보인다.'),
('n1-3932','2027-02-08','風車','かざぐるま','바람개비; 풍차','風を受けて羽根が回る玩具。また、風力を利用する装置を指すこともある。','子どもが色鮮やかな風車を持って走っている。','아이가 알록달록한 바람개비를 들고 뛰고 있다.'),
('n1-3933','2027-02-08','元年','がんねん','원년; 연호의 첫해','新しい年号・時代などの最初の年。また比喩的に、新しい取り組みが本格的に始まった年。','会社は今年を海外事業拡大の元年と位置付けている。','회사는 올해를 해외 사업 확대의 원년으로 규정하고 있다.'),
('n1-3934','2027-02-08','日向','ひなた','양지; 햇볕 드는 곳','日光が当たって明るく暖かい場所。','猫が窓辺の日向で気持ちよさそうに眠っている。','고양이가 창가 양지에서 기분 좋게 자고 있다.'),
('n1-3935','2027-02-08','道場','どうじょう','도장; 무예 수련장','柔道・剣道・空手などの武道や芸事を稽古する場所。','放課後になると道場から竹刀の音が聞こえてくる。','방과 후가 되면 도장에서 죽도 소리가 들려온다.'),
('n1-3936','2027-02-08','悪者','わるもの','악당; 나쁜 사람','悪いことをする人。また、周囲から悪い側の人物として扱われる人。','事情を単純化して、片方だけを悪者にするのは適切ではない。','사정을 단순화해 한쪽만 악당으로 모는 것은 적절하지 않다.'),
('n1-3937','2027-02-08','浜辺','はまべ','해변; 바닷가','海と陸地が接する砂浜などの場所、その周辺。','早朝の浜辺を歩きながら、漂着したごみを拾った。','이른 아침 해변을 걸으며 떠밀려 온 쓰레기를 주웠다.'),
('n1-3938','2027-02-08','旦那','だんな','남편; 주인어른','自分・他人の夫をややくだけていう語。また、古くは主人・雇い主などを敬っていう語。','彼女は旦那さんと相談してから参加するか決めるそうだ。','그녀는 남편과 상의한 뒤 참가할지 결정한다고 한다.'),
('n1-3939','2027-02-08','家来','けらい','가신; 부하','昔、主君に仕えて命令に従った武士・従者。','物語では忠実な家来が主君を危機から救う。','이야기에서는 충성스러운 가신이 주군을 위기에서 구한다.'),
('n1-3940','2027-02-08','喫茶','きっさ','차를 마심; 찻집','茶・コーヒーなどを飲むこと。『喫茶店』のように飲食店を表す語にも用いる。','駅前の喫茶店で資料を読みながら時間をつぶした。','역 앞 찻집에서 자료를 읽으며 시간을 보냈다.'),
('n1-3941','2027-02-09','家主','いえぬし','집주인; 가옥의 소유자','家・貸家の所有者。','修理費の負担について家主と相談することになった。','수리비 부담에 대해 집주인과 상담하기로 했다.'),
('n1-3942','2027-02-09','裸足','はだし','맨발','靴・靴下などを履いていない足、またはその状態。','子どもたちは砂浜を裸足で走り回っていた。','아이들은 모래사장을 맨발로 뛰어다니고 있었다.'),
('n1-3943','2027-02-09','真上','まうえ','바로 위; 정수리 위쪽','ある物・場所のちょうど垂直方向の上。','太陽がほぼ真上に来る時間帯は日差しが特に強い。','태양이 거의 바로 위에 오는 시간대에는 햇빛이 특히 강하다.'),
('n1-3944','2027-02-09','同級','どうきゅう','동급; 같은 학년·등급','同じ学年・級・等級であること。','彼とは高校で同級だったが、卒業後は別の道に進んだ。','그와는 고등학교에서 같은 학년이었지만 졸업 후에는 다른 길로 갔다.'),
('n1-3945','2027-02-09','教習','きょうしゅう','교습; 실기 교육','知識・技能を実際に教え、身につけさせること。特に運転などの技能教育に多く用いる。','免許を取るため、自動車学校で運転教習を受けている。','면허를 따기 위해 자동차 학원에서 운전 교습을 받고 있다.'),
('n1-3946','2027-02-09','大空','おおぞら','넓은 하늘; 창공','広々と果てしなく感じられる空。','鳥の群れが大空をゆっくり横切っていった。','새 떼가 넓은 하늘을 천천히 가로질러 갔다.'),
('n1-3947','2027-02-09','民宿','みんしゅく','민박; 민박집','一般の住宅などを利用し、旅行者に宿泊・食事を提供する小規模な宿泊施設。','旅行ではホテルではなく、地元の民宿に泊まった。','여행에서는 호텔이 아니라 현지 민박집에 묵었다.'),
('n1-3948','2027-02-09','水洗','すいせん','물로 씻음; 수세식','水で洗うこと。また、『水洗トイレ』のように水で流す方式を表す。','この素材は水洗できないため、専用の方法で手入れする必要がある。','이 소재는 물세탁할 수 없어 전용 방법으로 관리해야 한다.'),
('n1-3949','2027-02-09','雨具','あまぐ','우비; 비를 막는 장비','雨を防ぐために身につけたり使ったりするレインコート・傘などの道具。','山では天候が変わりやすいので、必ず雨具を持参してください。','산에서는 날씨가 변하기 쉬우니 반드시 우비 등 비 장비를 지참해 주세요.'),
('n1-3950','2027-02-09','天国','てんごく','천국; 천당; 낙원 같은 곳','宗教で、死後に幸福に暮らすとされる世界。また、非常に快適で理想的な場所を比喩的にいう。','温泉好きの彼にとって、各地の温泉を自由に巡れるこの町はまさに天国だ。','온천을 좋아하는 그에게 각지의 온천을 자유롭게 다닐 수 있는 이 도시는 그야말로 천국이다.'),
('n1-3951','2027-02-09','決勝','けっしょう','결승; 결승전','競技・大会で優勝者や最終的な勝者を決める最後の試合・段階。','準決勝を接戦で勝ち抜き、チームは三年ぶりに決勝へ進出した。','준결승을 접전 끝에 이겨 팀은 3년 만에 결승에 진출했다.'),
('n1-3952','2027-02-09','正解','せいかい','정답; 올바른 해답','問題・質問に対する正しい答え。また、判断・選択として適切なことを比喩的にいう場合もある。','一つの正解を覚えるだけでなく、なぜその答えになるのかを説明できるようにしたい。','하나의 정답만 외우는 것이 아니라 왜 그 답이 되는지 설명할 수 있게 하고 싶다.'),
('n1-3953','2027-02-09','受身','うけみ','수동; 수동태; 수세적인 태도','他からの動作を受ける文法形式。また、自分から積極的に動かない態度。','指示を待つだけの受身の姿勢では成長しにくい。','지시만 기다리는 수동적인 자세로는 성장하기 어렵다.'),
('n1-3954','2027-02-09','修学','しゅうがく','수학; 학문을 배움','学問や技術などを学び修めること。','海外で専門分野を修学した。','해외에서 전문 분야를 배웠다.'),
('n1-3955','2027-02-09','用法','ようほう','용법; 사용법','物や語句などの使い方。','この薬の正しい用法を確認してください。','이 약의 올바른 용법을 확인해 주세요.'),
('n1-3956','2027-02-09','教職','きょうしょく','교직; 교원 직업','学校などで学生・生徒を教える職業。','大学卒業後、教職に就いた。','대학 졸업 후 교직에 종사했다.'),
('n1-3957','2027-02-09','課外','かがい','과외; 정규 과정 밖','定められた授業・課程・勤務などの範囲外であること。','放課後に課外活動へ参加した。','방과 후에 과외 활동에 참가했다.'),
('n1-3958','2027-02-09','観','かん','모습; 인상; 느낌','外から見た様子・印象。特に『〜の観がある』『〜の観を呈する』などの形で用いる。','急造された制度であるため、全体として場当たり的な観が否めない。','급조된 제도이기 때문에 전체적으로 임시방편적이라는 인상을 부정하기 어렵다.'),
('n1-3959','2027-02-09','警部','けいぶ','경부; 일본 경찰의 계급 중 하나','日本の警察官の階級の一つで、警視の下、警部補の上に位置する。','現場の捜査を指揮する警部が記者会見で状況を説明した。','현장 수사를 지휘하는 경부가 기자회견에서 상황을 설명했다.'),
('n1-3960','2027-02-09','一敗','いっぱい','1패; 한 번의 패배','試合・勝負などで一度負けること。また、その一回の敗北。','チームは予選を三勝一敗で終え、決勝トーナメントへ進んだ。','팀은 예선을 3승 1패로 마치고 결승 토너먼트에 진출했다.');
INSERT INTO _n1_b10_words_0125(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3961','2027-02-10','主人公','しゅじんこう','주인공; 중심인물','小説・映画・演劇などの物語で中心となる人物。また、ある出来事の中心人物。','物語の主人公は失敗を重ねながら、少しずつ自分の生き方を見つけていく。','이야기의 주인공은 실패를 거듭하면서 조금씩 자신의 삶의 방식을 찾아간다.'),
('n1-3962','2027-02-10','極楽','ごくらく','극락; 낙원; 매우 편안한 곳이나 상태','仏教で、苦しみのない安楽な世界。また、非常に快適で心配のない場所・状態を比喩的にもいう。','温泉につかりながら雪景色を眺めていると、まるで極楽にいるような気分だった。','온천에 몸을 담그고 설경을 바라보니 마치 극락에 있는 듯한 기분이었다.'),
('n1-3963','2027-02-10','微笑','びしょう','미소','声を立てず、軽く笑うこと。','彼女は安心したように静かに微笑した。','그녀는 안심한 듯 조용히 미소 지었다.'),
('n1-3964','2027-02-10','冷蔵','れいぞう','냉장','食品などを低温で保存すること。','開封後は冷蔵して早めに食べてください。','개봉 후에는 냉장 보관하고 빨리 드세요.'),
('n1-3965','2027-02-10','年号','ねんごう','연호; 연대 이름','年を表すために用いる名称。特に日本の元号。','令和という年号は2019年から使われている。','레이와라는 연호는 2019년부터 사용되고 있다.'),
('n1-3966','2027-02-10','特技','とくぎ','특기; 장기','特に得意としている技能・技術。','彼女の特技は暗算だ。','그녀의 특기는 암산이다.'),
('n1-3967','2027-02-10','横綱','よこづな','요코즈나; 스모 최고 등급의 선수','大相撲で力士の最高位。','彼はついに横綱へ昇進した。','그는 마침내 요코즈나로 승진했다.'),
('n1-3968','2027-02-10','海路','うみじ','바닷길; 해로','船で海を通って行く道・航路。','一行は海路で島へ向かった。','일행은 바닷길로 섬을 향했다.'),
('n1-3969','2027-02-10','漁村','ぎょそん','어촌; 어촌 마을','漁業を主な生業とする人々が暮らす村。','その小さな漁村は新鮮な魚で有名だ。','그 작은 어촌은 신선한 생선으로 유명하다.'),
('n1-3970','2027-02-10','式場','しきじょう','식장; 예식장','式典・結婚式などを行う場所。','結婚式の一時間前に式場へ到着した。','결혼식 한 시간 전에 예식장에 도착했다.'),
('n1-3971','2027-02-10','砂利','じゃり','자갈; 자갈돌','小さな石が多数集まったもの。道路・庭などにも敷く。','庭の通路に砂利を敷いた。','정원 통로에 자갈을 깔았다.'),
('n1-3972','2027-02-10','共学','きょうがく','남녀 공학; 공학','男子と女子が同じ学校で一緒に学ぶこと。また、その制度。','その学校は十年前から男女共学になった。','그 학교는 10년 전부터 남녀공학이 되었다.'),
('n1-3973','2027-02-10','蜂蜜','はちみつ','꿀; 벌꿀','ミツバチが花の蜜を集め、巣に蓄えた甘い液体。','紅茶に蜂蜜を少し入れた。','홍차에 꿀을 조금 넣었다.'),
('n1-3974','2027-02-10','水気','すいき','수분; 습기','物に含まれている水分・湿気。','野菜の水気を十分に切ってから炒める。','채소의 물기를 충분히 뺀 뒤 볶는다.'),
('n1-3975','2027-02-10','花壇','かだん','화단','花を植えるために区切って作った場所。','学校の花壇にチューリップを植えた。','학교 화단에 튤립을 심었다.'),
('n1-3976','2027-02-10','担架','たんか','들것','負傷者・病人などを寝かせて運ぶための道具。','救急隊員が負傷者を担架で運んだ。','구급대원이 부상자를 들것으로 옮겼다.'),
('n1-3977','2027-02-10','油絵','あぶらえ','유화; 유채화','油絵具を使って描いた絵。','美術館で有名な油絵を鑑賞した。','미술관에서 유명한 유화를 감상했다.'),
('n1-3978','2027-02-10','短波','たんぱ','단파; 단파 전파','波長が比較的短い電波。一般に短波放送などに利用される。','短波放送は遠く離れた地域でも受信できることがある。','단파 방송은 멀리 떨어진 지역에서도 수신할 수 있는 경우가 있다.'),
('n1-3979','2027-02-10','大水','おおみず','큰물; 홍수; 불어난 물','大雨などによって川の水が大量に増えること。また、その水。','大雨で川が大水になり、周辺の道路が冠水した。','폭우로 강물이 크게 불어나 주변 도로가 침수됐다.'),
('n1-3980','2027-02-10','熱湯','ねっとう','끓는 물; 뜨거운 물','非常に熱い湯。特に、沸騰した湯。','熱湯を扱うときは、やけどに十分注意してください。','끓는 물을 다룰 때는 화상에 충분히 주의해 주세요.'),
('n1-3981','2027-02-11','三日月','みかづき','초승달; 가느다란 초승달 모양의 달','新月の後、細い弓形に見える月。','西の空に細い三日月が浮かんでいた。','서쪽 하늘에 가느다란 초승달이 떠 있었다.'),
('n1-3982','2027-02-11','貝殻','かいがら','조개껍데기; 조가비','貝の体を覆っている硬い殻。','浜辺で色のきれいな貝殻を拾った。','해변에서 색이 예쁜 조개껍데기를 주웠다.'),
('n1-3983','2027-02-11','一部分','いちぶぶん','일부분; 일부','全体の中の一つの部分。','資料の一部分だけを修正して提出した。','자료의 일부분만 수정해 제출했다.'),
('n1-3984','2027-02-11','蛋白質','たんぱくしつ','단백질','生物の体を構成する主要な栄養素の一つ。','肉や豆類には蛋白質が多く含まれる。','고기와 콩류에는 단백질이 많이 들어 있다.'),
('n1-3985','2027-02-11','明るい','あかるい','밝다; 전망이 좋다; ~에 정통하다','光が十分で明るい。性格・雰囲気が朗らかである。また『事情に明るい』の形で詳しいことを表す。','彼は現地の法律事情に明るいため、海外案件の相談役を務めている。','그는 현지 법률 사정에 밝아 해외 안건의 자문역을 맡고 있다.'),
('n1-3986','2027-02-11','役立つ','やくだつ','도움이 되다; 유용하다','ある目的を達成するために有用である。','過去の障害記録は、同じ問題が再発したときの原因分析に役立つ。','과거 장애 기록은 같은 문제가 재발했을 때 원인 분석에 도움이 된다.'),
('n1-3987','2027-02-11','大げさ','おおげさ','과장됨; 유난스러움','実際の程度以上に大きく、重大そうに表現するさま。','小さな失敗を必要以上に大げさに扱うべきではない。','작은 실패를 필요 이상으로 과장해서 다뤄서는 안 된다.'),
('n1-3988','2027-02-11','愚か','おろか','어리석다; 미련하다','考えが浅く、判断・行動が賢明でないさま。','同じ失敗を原因も調べず繰り返すのは愚かなことだ。','같은 실수를 원인도 조사하지 않고 반복하는 것은 어리석은 일이다.'),
('n1-3989','2027-02-11','任す','まかす','맡기다; 일임하다','仕事・判断・処理などを相手に委ね、その人の自由にさせる。','細かな実装方法は担当者に任すことにした。','세부 구현 방법은 담당자에게 맡기기로 했다.'),
('n1-3990','2027-02-11','鮮やか','あざやか','선명함; 산뜻함; 훌륭함','色・印象などがはっきりして美しいさま。また、技術・処理などが見事であるさま。','秋になると山々が鮮やかな赤や黄色に染まる。','가을이 되면 산들이 선명한 빨강과 노랑으로 물든다.'),
('n1-3991','2027-02-11','殴る','なぐる','때리다; 주먹으로 치다','手・こぶし、または手に持った物で相手を強く打つ。','口論になっても相手を殴る行為は決して許されない。','말다툼이 되어도 상대를 때리는 행위는 결코 용납되지 않는다.'),
('n1-3992','2027-02-11','物好き','ものずき','별난 것에 흥미를 보임; 그런 사람','普通の人なら関心を持たないような珍しいことを好んですること。また、その人。','雨の日にわざわざ山道を歩くとは、ずいぶん物好きだ。','비 오는 날 일부러 산길을 걷다니 꽤 별난 취향이다.'),
('n1-3993','2027-02-11','受かる','うかる','합격하다; 통과하다','試験・審査・検査などに合格する。','資格試験に受かるため、毎日少しずつ勉強を続けている。','자격시험에 합격하기 위해 매일 조금씩 공부를 이어가고 있다.'),
('n1-3994','2027-02-11','採用','さいよう','채용; 채택','人を選んで雇うこと。また、意見や方法などを取り上げて用いること。','新しい評価制度の採用に先立ち、全社員を対象とした説明会が開かれた。','새 평가 제도 채택에 앞서 전 직원을 대상으로 설명회가 열렸다。'),
('n1-3995','2027-02-11','専用','せんよう','전용','特定の人・目的・用途だけに使うこと。','機密情報を扱う端末は、一般業務とは分けた専用ネットワークに接続されている。','기밀 정보를 다루는 단말은 일반 업무와 분리된 전용 네트워크에 연결되어 있다.'),
('n1-3996','2027-02-11','調理','ちょうり','조리; 요리함','食材を切る・加熱する・味付けするなどして、食べられる料理にすること。','食中毒を防ぐため、肉は中心部まで十分に加熱して調理してください。','식중독을 막기 위해 고기는 중심부까지 충분히 가열하여 조리해 주세요.'),
('n1-3997','2027-02-11','日焼け','ひやけ','햇볕에 탐; 선탠','強い日光を浴びて皮膚の色が赤くなったり黒くなったりすること。','長時間外にいたので、腕がすっかり日焼けしてしまった。','오랫동안 밖에 있었더니 팔이 완전히 햇볕에 타 버렸다.'),
('n1-3998','2027-02-11','値引き','ねびき','할인; 가격 인하','商品の価格を、もとの値段より安くすること。','展示品だったため、通常価格から二割値引きして販売された。','전시품이었기 때문에 정상가에서 20% 할인해 판매되었다.'),
('n1-3999','2027-02-11','味わい','あじわい','맛; 풍미; 깊은 멋','食べ物・飲み物の味や風味。また、作品・経験などから感じられる深い趣。','古い木材を生かした店内には、新築にはない独特の味わいがある。','오래된 목재를 살린 가게 내부에는 신축 건물에는 없는 독특한 멋이 있다.'),
('n1-4000','2027-02-11','左利き','ひだりきき','왼손잡이','右手より左手を主に使う人。また、左手のほうが器用なこと。','彼は左利きなので、はさみも左手用のものを使っている。','그는 왼손잡이라 가위도 왼손용을 사용하고 있다.');
INSERT INTO _n1_b10_words_0125(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-4001','2027-02-12','後回し','あとまわし','뒤로 미룸; 뒷전','ある事をすぐ行わず、他の事を先にして後に回すこと。','重要だが急ぎでない課題を後回しにし続けると、いずれ問題が大きくなる。','중요하지만 급하지 않은 과제를 계속 뒤로 미루면 결국 문제가 커진다.'),
('n1-4002','2027-02-12','前置き','まえおき','서두; 본론 전에 하는 말','本題に入る前に述べる説明・言葉。','長い前置きは省いて、結論から説明してもらえますか。','긴 서두는 생략하고 결론부터 설명해 주실 수 있나요?'),
('n1-4003','2027-02-12','無駄遣い','むだづかい','낭비; 헛씀','金銭・時間・物などを、必要性や効果の乏しいことに使うこと。','予算の無駄遣いを防ぐため、支出項目を定期的に見直している。','예산 낭비를 막기 위해 지출 항목을 정기적으로 재검토하고 있다.'),
('n1-4004','2027-02-12','使い道','つかいみち','용도; 쓰임새','物・金・時間などを何のために使うかという用途。','助成金の使い道について、具体的な計画書を提出する必要がある。','지원금의 용도에 대해 구체적인 계획서를 제출할 필요가 있다.'),
('n1-4005','2027-02-12','身体','からだ','몸; 신체','人・動物の体全体。身体。','無理をせず、身体を大切にしてください。','무리하지 말고 몸을 소중히 하세요.'),
('n1-4006','2027-02-12','従業員','じゅうぎょういん','종업원; 직원; 근로자','会社・店などに雇われ、その業務に従事する人。','この会社では約五百人の従業員が働いている。','이 회사에서는 약 500명의 직원이 일하고 있다.'),
('n1-4007','2027-02-12','帰京','ききょう','도쿄로 돌아감; 귀경(도쿄 귀환)','地方などから東京へ戻ること。','出張を終え、明日の朝に帰京する予定だ。','출장을 마치고 내일 아침 도쿄로 돌아갈 예정이다.'),
('n1-4008','2027-02-12','使用人','しようにん','고용인; 사용인; 피고용인','雇われて働く人。特に家事などに従事する人を指すこともある。','昔、その屋敷には多くの使用人がいた。','옛날 그 저택에는 많은 고용인이 있었다.'),
('n1-4009','2027-02-12','漢語','かんご','한어; 한자어; 일본어의 한자계 어휘','中国語から入った語、または漢字の音を用いて作られた日本語の語。','『文化』や『経済』は漢語の例として挙げられる。','''文化''나 ''経済''는 한자어의 예로 들 수 있다.'),
('n1-4010','2027-02-12','縁側','えんがわ','툇마루; 일본식 집의 가장자리 마루','和風建築で、部屋の外側に沿って設けられた細長い板敷きの部分。','祖母は縁側に座って庭を眺めていた。','할머니는 툇마루에 앉아 정원을 바라보고 계셨다.'),
('n1-4011','2027-02-12','桟橋','さんきょう','잔교; 부두; 선착장','船の乗り降りや荷物の積み下ろしのため、水上へ突き出して設けた橋状の施設。','船が桟橋に着いた。','배가 선착장에 도착했다.'),
('n1-4012','2027-02-12','碁盤','ごばん','바둑판','囲碁を打つための盤。','祖父は古い碁盤を大切に使っている。','할아버지는 오래된 바둑판을 소중히 사용하고 계신다.'),
('n1-4013','2027-02-12','分母','ぶんぼ','분모','分数で横線の下にある数・式。','分母をそろえてから計算する。','분모를 통일한 뒤 계산한다.'),
('n1-4014','2027-02-12','縁談','えんだん','혼담; 결혼 이야기','結婚について持ち上がる話・相談。','親戚から縁談を持ちかけられた。','친척에게서 혼담을 제안받았다.'),
('n1-4015','2027-02-12','時刻表','じこくひょう','시각표; 시간표; 운행 시간표','列車・バス・船などの発着時刻をまとめた表。','駅の時刻表で次の電車を確認した。','역의 시간표에서 다음 전철을 확인했다.'),
('n1-4016','2027-02-12','和文','わぶん','일본어 문장; 일본문; 일본어 글','日本語で書かれた文章。特に外国語文に対する日本語文。','英文を和文に訳す練習をした。','영문을 일본어 문장으로 번역하는 연습을 했다.'),
('n1-4017','2027-02-12','軍服','ぐんぷく','군복','軍人が着用する制服。','博物館に昔の軍服が展示されている。','박물관에 옛 군복이 전시되어 있다.'),
('n1-4018','2027-02-12','還暦','かんれき','환갑; 회갑; 만 60세 생일','数え年の干支が一巡して、生まれた年の干支に戻る六十歳の祝い。また、六十歳そのもの。','父の還暦を祝って家族で食事会を開いた。','아버지의 환갑을 축하해 가족끼리 식사 모임을 열었다.'),
('n1-4019','2027-02-12','三味線','さみせん','샤미센; 일본의 삼현악기','三本の弦を持ち、ばちで弾く日本の伝統的な弦楽器。','祭りで三味線の演奏を初めて聞いた。','축제에서 처음으로 샤미센 연주를 들었다.'),
('n1-4020','2027-02-12','香辛料','こうしんりょう','향신료; 스파이스','料理に香り・辛味・風味を加える調味料。','この料理には数種類の香辛料が使われている。','이 요리에는 여러 종류의 향신료가 사용된다.'),
('n1-4021','2027-02-13','十字路','じゅうじろ','사거리; 네거리','道路が十字形に交差して四方向へ分かれる場所。','次の十字路を右に曲がってください。','다음 사거리에서 오른쪽으로 도세요.'),
('n1-4022','2027-02-13','冬眠','とうみん','동면; 겨울잠','動物が冬の間、活動を大きく低下させて過ごすこと。','熊は冬眠に備えて秋に多くの餌を食べる。','곰은 겨울잠에 대비해 가을에 많은 먹이를 먹는다.'),
('n1-4023','2027-02-13','一部','いちぶ','일부; 한 부분','全体の中のある部分。','資料の一部に誤りが見つかったため、該当箇所を修正した。','자료의 일부에서 오류가 발견되어 해당 부분을 수정했다。'),
('n1-4024','2027-02-13','不明','ふめい','불명; 불명확함','明らかでなく、はっきり分からないこと。','事故の詳しい原因は依然として不明のままだ。','사고의 자세한 원인은 여전히 밝혀지지 않은 상태다。'),
('n1-4025','2027-02-13','通常','つうじょう','통상; 보통; 일반적으로','特別な事情がない普通の状態。また、一般的には。','通常は三営業日以内に結果を通知しますが、繁忙期は遅れる場合があります。','통상은 영업일 기준 3일 이내에 결과를 통지하지만, 성수기에는 늦어질 수 있습니다。'),
('n1-4026','2027-02-13','日々','ひび','나날; 매일매일','一日一日。毎日の暮らしや、その積み重なり。','技術は日々進歩しているため、継続して学ぶ姿勢が欠かせない。','기술은 나날이 발전하고 있기 때문에 계속 배우는 자세가 필수적이다.'),
('n1-4027','2027-02-13','本気','ほんき','진심; 진지함; 본심','冗談や遊びではなく、真剣に物事に取り組もうとする気持ちや態度。','本気で転職を考えるなら、希望条件だけでなく自分の強みも整理したほうがいい。','진지하게 이직을 생각한다면 희망 조건뿐 아니라 자신의 강점도 정리하는 편이 좋다.'),
('n1-4028','2027-02-13','不良','ふりょう','불량; 좋지 않음; 결함','品質・状態・成績・行動などが正常または望ましい基準に達していないこと。','検査工程で不良品が見つかったため、同じ製造ロットをすべて確認した。','검사 공정에서 불량품이 발견되어 같은 제조 로트를 모두 확인했다.'),
('n1-4029','2027-02-13','保つ','たもつ','유지하다; 보존하다; 지키다','状態・品質・関係・健康などを変わらないよう維持する。','長時間集中力を保つには、適度に休憩を取ることが重要だ。','장시간 집중력을 유지하려면 적절히 휴식을 취하는 것이 중요하다.'),
('n1-4030','2027-02-13','華やか','はなやか','화려함; 눈부시고 밝음','色彩・雰囲気・経歴などが明るく美しく、目立って人目を引くさま。','華やかな舞台の裏では、多くのスタッフが地道な準備を続けている。','화려한 무대 뒤에서는 많은 스태프가 꾸준히 준비를 이어 가고 있다.'),
('n1-4031','2027-02-13','間もなく','まもなく','곧; 머지않아','それほど時間が経たないうちに。すぐに。','点検は最終段階に入っており、サービスは間もなく再開される見込みだ。','점검은 최종 단계에 들어갔으며 서비스는 곧 재개될 전망이다.'),
('n1-4032','2027-02-13','名高い','なだかい','이름난; 명성이 높은; 유명한','優れた点・業績などによって、世間に広く名を知られている。','この地方は美しい紅葉の名所として全国に名高い。','이 지방은 아름다운 단풍 명소로 전국적으로 이름이 높다.'),
('n1-4033','2027-02-13','間違う','まちがう','틀리다; 잘못하다; 착각하다','判断・答え・方法などが正しくない状態になる。また、誤った行動をする。','入力する番号を一桁間違うだけでも、別のデータが処理される可能性がある。','입력할 번호를 한 자리만 틀려도 다른 데이터가 처리될 가능성이 있다.'),
('n1-4034','2027-02-13','混む','こむ','붐비다; 혼잡하다','人・車などが多く集まり、混雑する。','この道路は朝になると非常に混む。','이 도로는 아침이 되면 매우 붐빈다.'),
('n1-4035','2027-02-13','平たい','ひらたい','납작하다; 평평하다; 쉬운 말로 풀어쓴','表面が平らで広がっている。また、表現などが分かりやすく平易なさま。','平たい皿に料理を盛り付けた。','평평한 접시에 음식을 담았다.'),
('n1-4036','2027-02-13','引き下げる','ひきさげる','낮추다; 인하하다; 끌어내리다','価格・水準・地位などを低くする。また、いったん出したものを取り下げる。','会社は来月から商品の価格を引き下げると発表した。','회사는 다음 달부터 상품 가격을 인하한다고 발표했다.'),
('n1-4037','2027-02-13','休める','やすめる','쉬게 하다; 쉬다; 사용을 멈추다','体・手足・道具などを休ませる。また、使用・活動を一時止める。','疲れを感じたら、少し目を閉じて体を休めるといい。','피로를 느끼면 잠시 눈을 감고 몸을 쉬게 하는 것이 좋다.'),
('n1-4038','2027-02-13','割り込む','わりこむ','끼어들다; 새치기하다; 중간에 끼어들다','列・会話・作業などの途中に無理に入り込む。','人の話に突然割り込むのは失礼だ。','남의 말에 갑자기 끼어드는 것은 실례다.'),
('n1-4039','2027-02-13','爽やか','さわやか','상쾌하다; 산뜻하다; 개운하다','気分・天気・印象などがすっきりして心地よいさま。','朝の爽やかな風が気持ちいい。','아침의 상쾌한 바람이 기분 좋다.'),
('n1-4040','2027-02-13','扱い','あつかい','취급; 대우; 처리 방식','物事を取り扱う方法。また、人に対する待遇・位置付け。','機密資料は通常の文書とは異なる扱いが必要だ。','기밀 자료는 일반 문서와 다른 취급이 필요하다.');
INSERT INTO _n1_b10_words_0125(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-4041','2027-02-14','怒り','いかり','분노; 화','腹立たしさ・不満などから生じる強い感情。','説明不足に対する住民の怒りは、時間がたつほど強まっていった。','설명 부족에 대한 주민들의 분노는 시간이 지날수록 커졌다.'),
('n1-4042','2027-02-14','遅れ','おくれ','지연; 늦음; 뒤처짐','予定・基準・他のものより遅れること。また、その差。','開発の遅れを取り戻すために、工程を見直して人員を再配置した。','개발 지연을 만회하기 위해 공정을 재검토하고 인력을 재배치했다.'),
('n1-4043','2027-02-14','助け','たすけ','도움; 구원','困っている人を支えたり、危険から救ったりすること。','周囲の助けがなければ、短期間でこの仕事を終えることはできなかった。','주변의 도움이 없었다면 짧은 기간에 이 일을 끝낼 수 없었다.'),
('n1-4044','2027-02-14','勧め','すすめ','권유; 추천','人にある行動・選択をするよう勧めること。また、その内容。','医師の勧めで、毎日少しずつ運動する習慣を始めた。','의사의 권유로 매일 조금씩 운동하는 습관을 시작했다.'),
('n1-4045','2027-02-14','行い','おこない','행동; 행실','人が実際にする行動。特に道徳的な観点から見た行為・品行。','日頃の行いは、いざという時の周囲からの信頼にも影響する。','평소의 행동은 만일의 때 주변의 신뢰에도 영향을 준다.'),
('n1-4046','2027-02-14','結び','むすび','맺음; 결론; 매듭','物事・文章などの最後の部分。また、結び付けることや結び目。','発表の結びでは、今後の課題と展望を簡潔にまとめた。','발표의 맺음에서는 향후 과제와 전망을 간결하게 정리했다.'),
('n1-4047','2027-02-14','恐れ','おそれ','두려움; 우려; 가능성','恐怖・不安。また『〜する恐れがある』の形で、好ましくない可能性を表す。','大雨が続くと河川が氾濫する恐れがあるため、早めの避難が必要だ。','폭우가 계속되면 하천이 범람할 우려가 있어 조기 대피가 필요하다.'),
('n1-4048','2027-02-14','並み','なみ','보통 수준; ~와 같은 정도','普通と同じ程度であること。また『人並み』『例年並み』のように同程度を表す。','今年の降水量は例年並みだが、地域による差が大きい。','올해 강수량은 예년 수준이지만 지역별 차이가 크다.'),
('n1-4049','2027-02-14','覚え','おぼえ','기억; 기억하고 있음; 익힌 정도','記憶していること。また、身に覚えがあることや、物事を覚える能力・程度。','その契約に署名した覚えがないため、記録を確認してほしい。','그 계약에 서명한 기억이 없어 기록을 확인해 주길 바란다.'),
('n1-4050','2027-02-14','写し','うつし','사본; 복사본','原本を書き写したり複製したりしたもの。','本人確認のため、身分証明書の写しを提出してください。','본인 확인을 위해 신분증 사본을 제출해 주세요.'),
('n1-4051','2027-02-14','情け','なさけ','인정; 자비; 연민','他人の苦しみ・事情を思いやる心。人情や慈悲。','困っている人に情けをかけるだけでなく、自立につながる支援も必要だ。','곤란한 사람에게 인정을 베푸는 것뿐 아니라 자립으로 이어지는 지원도 필요하다.'),
('n1-4052','2027-02-14','申し込み','もうしこみ','신청; 접수','参加・契約・利用などを希望して、必要な手続きをすること。','研修への申し込みは今週金曜日で締め切られる。','연수 신청은 이번 주 금요일에 마감된다.'),
('n1-4053','2027-02-14','悩み','なやみ','고민; 걱정거리','解決できず心を苦しめている問題・心配。','一人で悩みを抱え込まず、早めに周囲へ相談した方がいい。','혼자 고민을 끌어안지 말고 일찍 주변에 상담하는 편이 좋다.'),
('n1-4054','2027-02-14','驚き','おどろき','놀람; 놀라움','予想外のことに接して強くびっくりすること。また、その感情。','予想を大きく上回る結果に、会場から驚きの声が上がった。','예상을 크게 웃도는 결과에 행사장에서 놀라움의 목소리가 나왔다.'),
('n1-4055','2027-02-14','叫び','さけび','외침; 고함','大声で叫ぶこと。また、強い感情・要求を表す声や訴え。','助けを求める叫びを聞き、近くにいた人が消防へ通報した。','도움을 청하는 외침을 듣고 근처에 있던 사람이 소방에 신고했다.'),
('n1-4056','2027-02-14','頼み','たのみ','부탁; 의지할 대상; 기대','相手に何かをしてほしいとお願いすること。また、頼りにする人・物・希望。','急な頼みだったが、同僚は快く引き受けてくれた。','갑작스러운 부탁이었지만 동료는 흔쾌히 맡아 주었다.'),
('n1-4057','2027-02-14','救い','すくい','구원; 구제; 위안이 되는 것','危険・苦しみ・困難などから助け出すこと。また、絶望の中で支えや希望となるもの。','厳しい状況の中で、仲間からの言葉が唯一の救いだった。','힘든 상황 속에서 동료의 말이 유일한 위안이었다.'),
('n1-4058','2027-02-14','身振り','みぶり','몸짓; 제스처','意思・感情などを表すために、手・体を動かすこと。また、その動作。','言葉が通じなくても、身振りを交えればある程度は意思を伝えられる。','말이 통하지 않아도 몸짓을 섞으면 어느 정도 의사를 전달할 수 있다.'),
('n1-4059','2027-02-14','締め切り','しめきり','마감; 기한','応募・提出・受付などを終了する期限・時刻。','申請の締め切りは今月末なので、早めに必要書類を準備してください。','신청 마감은 이달 말이므로 필요한 서류를 미리 준비해 주세요.'),
('n1-4060','2027-02-14','張り紙','はりがみ','붙임쪽지; 벽보; 안내문','知らせ・注意などを書き、壁・掲示板などに貼った紙。','入口の張り紙には臨時休業のお知らせが書かれていた。','입구의 안내문에는 임시 휴업 공지가 적혀 있었다.'),
('n1-4061','2027-02-15','共働き','ともばたらき','맞벌이','夫婦などの双方が仕事を持って働くこと。','共働き世帯の増加に伴い、保育サービスの需要も高まっている。','맞벌이 가구 증가에 따라 보육 서비스 수요도 높아지고 있다.'),
('n1-4062','2027-02-15','夕暮れ','ゆうぐれ','해질녘; 황혼','日が沈み始めて、次第に暗くなるころ。','夕暮れになると海岸沿いの気温が急に下がった。','해질녘이 되자 해안가 기온이 급격히 내려갔다.'),
('n1-4063','2027-02-15','開発','かいはつ','개발','土地・資源・技術・製品などを実用化し、価値を高めること。','新しい医療機器の開発には、長期間の試験と検証が必要だ。','새로운 의료기기 개발에는 장기간의 시험과 검증이 필요하다。'),
('n1-4064','2027-02-15','保護','ほご','보호','危険や損害を受けないように守ること。','希少な動植物を保護するため、この地域への立ち入りが制限されている。','희귀한 동식물을 보호하기 위해 이 지역의 출입이 제한되어 있다。'),
('n1-4065','2027-02-15','施設','しせつ','시설','特定の目的のために設けられた建物や設備。','この施設は災害時に一時避難所として利用される。','이 시설은 재해 시 임시 대피소로 이용된다。'),
('n1-4066','2027-02-15','提供','ていきょう','제공','必要とされる物・情報・サービスなどを差し出すこと。','利用者に正確な情報を提供することが、このサービスの役割だ。','이용자에게 정확한 정보를 제공하는 것이 이 서비스의 역할이다。'),
('n1-4067','2027-02-15','殺人','さつじん','살인','人を故意に殺すこと。','警察は殺人事件として捜査を進め、目撃情報を集めている。','경찰은 살인 사건으로 수사를 진행하며 목격 정보를 모으고 있다。'),
('n1-4068','2027-02-15','現場','げんじょう','현장; 사건 현장','事件や事故などが実際に起きた場所。','捜査員は現場に残されたわずかな痕跡を慎重に調べた。','수사관은 현장에 남은 작은 흔적을 신중하게 조사했다。'),
('n1-4069','2027-02-15','選挙','せんきょ','선거','投票によって代表者や役員などを選ぶこと。','今回の選挙では若年層の投票率が大きな焦点となっている。','이번 선거에서는 젊은 층의 투표율이 큰 쟁점이 되고 있다。'),
('n1-4070','2027-02-15','自己','じこ','자기; 자신','その人自身。自分自身。','自己の利益だけでなく、社会全体への影響も考える必要がある。','자신의 이익뿐 아니라 사회 전체에 미치는 영향도 생각할 필요가 있다。'),
('n1-4071','2027-02-15','資金','しきん','자금','事業や活動など、特定の目的のために用いる金銭。','研究を継続するには、来年度の資金を早めに確保しなければならない。','연구를 계속하려면 내년도 자금을 조기에 확보해야 한다。'),
('n1-4072','2027-02-15','距離','きょり','거리; 간격','二つの地点や物の間がどれだけ離れているかを表す長さ。','駅から会場までかなり距離があるため、バスを利用したほうがよい。','역에서 행사장까지 거리가 꽤 있어서 버스를 이용하는 편이 좋다。'),
('n1-4073','2027-02-15','保険','ほけん','보험','事故・病気・災害などに備え、一定の負担と引き換えに補償を受ける制度。','海外赴任に備えて、補償内容の広い保険に加入した。','해외 부임에 대비해 보장 범위가 넓은 보험에 가입했다。'),
('n1-4074','2027-02-15','勝利','しょうり','승리','戦いや試合などで相手に勝つこと。','チームは最後まで集中力を切らさず、接戦の末に勝利を収めた。','팀은 끝까지 집중력을 잃지 않고 접전 끝에 승리를 거두었다。'),
('n1-4075','2027-02-15','投資','とうし','투자','将来の利益や成果を期待して、資金・時間・労力などを投入すること。','短期的な利益だけでなく、人材育成への投資も企業の成長には欠かせない。','단기 이익뿐 아니라 인재 육성에 대한 투자도 기업 성장에는 필수적이다。'),
('n1-4076','2027-02-15','文書','ぶんしょ','문서; 문건','文字で内容を記録したもの。特に、保存・伝達・証明などに用いる書類。','契約条件を変更する場合は、口頭ではなく文書で合意を残してください。','계약 조건을 변경할 경우 구두가 아니라 문서로 합의를 남겨 주세요。'),
('n1-4077','2027-02-15','治療','ちりょう','치료','病気やけがを治すために、医学的な処置を行うこと。','早期に適切な治療を受ければ、回復までの期間を短くできる可能性がある。','조기에 적절한 치료를 받으면 회복 기간을 줄일 가능성이 있다。'),
('n1-4078','2027-02-15','参照','さんしょう','참조; 참고','他の資料や情報と照らし合わせ、参考にすること。','申請方法の詳細については、公式サイトの案内を参照してください。','신청 방법의 자세한 내용은 공식 사이트 안내를 참고해 주세요。'),
('n1-4079','2027-02-15','設定','せってい','설정; 정함; 지정','条件・数値・場所・役割などを目的に応じて決め、定めること。','新しい端末を使う前に、言語と時刻の設定を確認してください。','새 단말기를 사용하기 전에 언어와 시간 설정을 확인해 주세요.'),
('n1-4080','2027-02-15','美術','びじゅつ','미술','絵画や彫刻など、視覚的な形で美を表現する芸術。','この美術館では近代美術を中心に国内外の作品を展示している。','이 미술관에서는 근대 미술을 중심으로 국내외 작품을 전시하고 있다。');
INSERT INTO _n1_b10_words_0125(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-4081','2027-02-16','派遣','はけん','파견; 파송','一定の任務を与えて、人をある場所へ送り出すこと。','会社は新工場の立ち上げ支援のため、経験豊富な技術者を現地へ派遣した。','회사는 새 공장 가동 지원을 위해 경험 많은 기술자를 현지로 파견했다。'),
('n1-4082','2027-02-16','同意','どうい','동의','他人の意見や提案を認め、賛成すること。','個人情報を第三者に提供する場合は、原則として本人の同意が必要だ。','개인정보를 제3자에게 제공할 경우 원칙적으로 본인의 동의가 필요하다。'),
('n1-4083','2027-02-16','公開','こうかい','공개','情報や作品などを広く一般の人に見せたり知らせたりすること。','調査結果は来月、公式サイトで一般に公開される予定だ。','조사 결과는 다음 달 공식 사이트에서 일반에 공개될 예정이다。'),
('n1-4084','2027-02-16','地元','じもと','고장; 지역; 현지','自分が住んでいる、または関係の深い地域。その場所の地域社会。','祭りの運営には地元の住民や商店が毎年協力している。','축제 운영에는 지역 주민과 상점들이 매년 협력하고 있다。'),
('n1-4085','2027-02-16','設置','せっち','설치','設備や機関などを、目的に応じて一定の場所に設けること。','事故防止のため、駅のホームに新しい安全柵が設置された。','사고 방지를 위해 역 승강장에 새로운 안전 펜스가 설치되었다。'),
('n1-4086','2027-02-16','反応','はんのう','반응','刺激や働きかけを受けた結果として現れる変化、動作、態度。','新商品の発表に対する消費者の反応は予想以上に好意的だった。','신제품 발표에 대한 소비자 반응은 예상 이상으로 호의적이었다。'),
('n1-4087','2027-02-16','古代','こだい','고대','歴史上、原始時代の後から中世より前までにあたる遠い昔の時代。','発掘調査によって、この地域に古代の集落が存在したことが分かった。','발굴 조사를 통해 이 지역에 고대 취락이 존재했다는 사실이 밝혀졌다。'),
('n1-4088','2027-02-16','購入','こうにゅう','구입; 구매','代金を支払って商品や物品を買い入れること。','高額な機器を購入する前に、複数の製品を比較して性能を確認した。','고가 장비를 구입하기 전에 여러 제품을 비교해 성능을 확인했다。'),
('n1-4089','2027-02-16','開催','かいさい','개최','集会・行事・試合などを計画して開くこと。','国際会議は来年五月に東京で開催される予定だ。','국제회의는 내년 5월에 도쿄에서 개최될 예정이다。'),
('n1-4090','2027-02-16','内部','ないぶ','내부; 안쪽; 조직 내부','物や組織などの内側、またはその範囲。','調査委員会は事故原因だけでなく、組織内部の管理体制も検証した。','조사위원회는 사고 원인뿐 아니라 조직 내부의 관리 체계도 검증했다。'),
('n1-4091','2027-02-16','予想','よそう','예상; 예측','将来起こることや結果について、前もって見当をつけること。','予想を上回る応募があったため、受付期間を早めに終了した。','예상을 웃도는 응모가 있어 접수 기간을 일찍 종료했다。'),
('n1-4092','2027-02-16','登録','とうろく','등록','氏名や情報などを所定の帳簿・名簿・システムに記載して正式に扱える状態にすること。','サービスを利用するには、事前にメールアドレスを登録する必要がある。','서비스를 이용하려면 사전에 이메일 주소를 등록해야 한다。'),
('n1-4093','2027-02-16','伝説','でんせつ','전설','昔から人々の間で語り伝えられてきた話。','この湖には、昔から巨大な魚がすむという伝説が残っている。','이 호수에는 예부터 거대한 물고기가 산다는 전설이 남아 있다。'),
('n1-4094','2027-02-16','軍事','ぐんじ','군사','軍隊・兵器・戦争など、軍に関する事柄。','両国は緊張の高まりを受け、軍事面での対話を再開した。','양국은 긴장이 고조됨에 따라 군사 분야의 대화를 재개했다。'),
('n1-4095','2027-02-16','手配','てはい','수배; 준비; 주선','必要な人・物・手段などを前もって準備したり取り決めたりすること。また、警察が容疑者などを捜して逮捕できるよう関係先に連絡すること。','出張が決まったので、担当者に航空券と宿泊先の手配を依頼した。','출장이 결정되어 담당자에게 항공권과 숙박 장소의 준비를 부탁했다。'),
('n1-4096','2027-02-16','固定','こてい','고정','動いたり変化したりしないよう一定の位置・状態に保つこと。','作業中に部品が動かないよう、専用の器具でしっかり固定する。','작업 중 부품이 움직이지 않도록 전용 기구로 단단히 고정한다。'),
('n1-4097','2027-02-16','戦闘','せんとう','전투','軍隊などが武器を用いて敵と戦うこと。','停戦合意が発効し、国境付近で続いていた戦闘はいったん収まった。','정전 합의가 발효되어 국경 부근에서 계속되던 전투가 일단 진정되었다。'),
('n1-4098','2027-02-16','体験','たいけん','체험; 직접 경험','自分自身が実際に行ったり経験したりすること。また、その経験。','留学中に現地の家庭で生活した体験は、価値観を見直すきっかけになった。','유학 중 현지 가정에서 생활한 체험은 가치관을 다시 생각하는 계기가 되었다。'),
('n1-4099','2027-02-16','指示','しじ','지시; 지시 사항','何をどのようにするかを示して命じること。また、その内容。','責任者の指示があるまでは、現場の設備に触れないでください。','책임자의 지시가 있을 때까지 현장 설비에 손대지 마십시오。'),
('n1-4100','2027-02-16','同士','どうし','서로 같은 부류끼리; ~끼리','同じ立場・性質・関係などを持つ者どうしであることを表す語。','同じ業界の企業同士が協力し、共通の安全基準を作った。','같은 업계의 기업끼리 협력해 공통 안전 기준을 만들었다.'),
('n1-4101','2027-02-17','一言','いちげん','한마디; 한마디 말','一つの言葉、または短い発言。『いちごん』『ひとこと』とも読むが、この項目では『いちげん』の読みを扱う。','会議の最後に、責任者として一言申し上げたい。','회의 마지막에 책임자로서 한마디 말씀드리고 싶다.'),
('n1-4102','2027-02-17','部下','ぶか','부하; 하급 직원','職場などで、自分より下の地位にあり、自分の指示を受けて働く人。','上司には、部下が相談しやすい環境を整える責任もある。','상사에게는 부하 직원이 상담하기 쉬운 환경을 마련할 책임도 있다.'),
('n1-4103','2027-02-17','地獄','じごく','지옥; 극도로 괴로운 상태','宗教上、罪を犯した者が死後に罰を受けるとされる世界。転じて、非常に苦しく悲惨な状態。','真夏の停電で冷房が止まり、満員の室内は地獄のような暑さだった。','한여름 정전으로 냉방이 멈춰 사람들로 가득 찬 실내는 지옥 같은 더위였다.'),
('n1-4104','2027-02-17','職員','しょくいん','직원; 교직원·공무원 등의 직원','学校・役所・施設など一定の組織に所属し、その仕事を担当する人。','避難訓練では、職員が利用者を安全な場所まで誘導した。','대피 훈련에서는 직원들이 이용자를 안전한 장소까지 유도했다.'),
('n1-4105','2027-02-17','箇所','かしょ','곳; 부분; 개소','ある場所や文章などの中の特定の部分。場所を数える際にも用いる。','申請書に記入漏れの箇所が二つあるので、提出前に修正してください。','신청서에 빠진 부분이 두 군데 있으니 제출 전에 수정해 주세요.'),
('n1-4106','2027-02-17','貴族','きぞく','귀족','歴史上、特権的な高い身分や社会的地位を持った階級、またはその階級に属する人。','この城はかつて有力な貴族の住居として使われていた。','이 성은 과거 유력한 귀족의 거처로 사용되었다.'),
('n1-4107','2027-02-17','上司','じょうし','상사','職場や組織で、自分より職位や立場が上の人。','判断に迷ったため、まず上司に状況を報告して指示を仰いだ。','판단이 어려워 우선 상사에게 상황을 보고하고 지시를 구했다.'),
('n1-4108','2027-02-17','了解','りょうかい','이해; 승낙; 알겠음','事情や内容を理解し、それを受け入れること。また、連絡などに対して理解した旨を示すこと。','日程変更の件は了解しました。関係者にもこちらから連絡します。','일정 변경 건은 이해했습니다. 관계자에게도 제가 연락하겠습니다.'),
('n1-4109','2027-02-17','現地','げんち','현지; 현장 지역','実際にその出来事や活動が行われている場所・地域。','正確な被害状況を確認するため、調査員を現地に派遣した。','정확한 피해 상황을 확인하기 위해 조사원을 현지에 파견했다.'),
('n1-4110','2027-02-17','天才','てんさい','천재','生まれつき非常に優れた才能を持つ人。また、その並外れた才能。','彼は天才と評されたが、その成果の裏には長年の地道な努力もあった。','그는 천재라는 평가를 받았지만 그 성과 뒤에는 오랜 기간의 꾸준한 노력도 있었다.'),
('n1-4111','2027-02-17','燃料','ねんりょう','연료','燃焼などによって熱や動力などのエネルギーを得るために使う物質。','燃料価格の上昇が続けば、輸送費にも影響が広がる可能性がある。','연료 가격 상승이 계속되면 운송비에도 영향이 확대될 가능성이 있다.'),
('n1-4112','2027-02-17','挑戦','ちょうせん','도전','困難な課題や相手に対して、成功や勝利を目指して立ち向かうこと。','経験のない分野にも挑戦したことで、仕事の幅が大きく広がった。','경험이 없는 분야에도 도전하면서 업무의 폭이 크게 넓어졌다.'),
('n1-4113','2027-02-17','恋愛','れんあい','연애; 사랑','人が特定の相手に恋愛感情を抱き、互いに愛情を深めたり交際したりすること。','仕事と恋愛をどう両立するかについて、二人で率直に話し合った。','일과 연애를 어떻게 병행할지 두 사람이 솔직하게 이야기했다.'),
('n1-4114','2027-02-17','出演','しゅつえん','출연','映画・舞台・テレビ・ラジオなどに出て、演技・演奏・発言などをすること。','人気俳優が新作ドラマに出演することが正式に発表された。','인기 배우가 새 드라마에 출연한다는 사실이 공식 발표되었다.'),
('n1-4115','2027-02-17','後悔','こうかい','후회','過去にしたことやしなかったことを振り返り、誤りだった、または別の選択をすべきだったと悔やむこと。','準備不足のまま決断したことを後悔しても、失った時間は戻らない。','준비가 부족한 채로 결정한 것을 후회해도 잃은 시간은 돌아오지 않는다.'),
('n1-4116','2027-02-17','乗客','じょうかく','승객; 탑승객','列車・バス・船・航空機などの乗り物に客として乗っている人。','事故の影響で、乗客は一時車内に待機するよう案内された。','사고의 영향으로 승객들은 한동안 차량 안에서 대기하도록 안내받았다.'),
('n1-4117','2027-02-17','英雄','えいゆう','영웅','優れた勇気や能力によって大きな功績を成し遂げ、人々から高く評価される人物。','彼は戦争の英雄として語られてきたが、近年はその評価を見直す研究も増えている。','그는 전쟁 영웅으로 이야기되어 왔지만 최근에는 그 평가를 재검토하는 연구도 늘고 있다.'),
('n1-4118','2027-02-17','読者','どくしゃ','독자','本・新聞・雑誌・記事などを読む人。','専門用語を減らし、一般の読者にも理解しやすい文章に書き直した。','전문용어를 줄여 일반 독자도 이해하기 쉬운 문장으로 다시 썼다.'),
('n1-4119','2027-02-17','天井','てんじょう','천장; 상한','部屋などの上部を覆う面。また、価格や数量などの上限を比喩的にいう場合もある。','古い建物なので、雨が強い日は天井から水が漏れることがある。','오래된 건물이라 비가 많이 오는 날에는 천장에서 물이 샐 때가 있다.'),
('n1-4120','2027-02-17','無線','むせん','무선; 무선통신','電線を使わず、電波などによって通信すること。また、その方式や装置。','会議室では有線接続だけでなく、無線ネットワークも利用できる。','회의실에서는 유선 연결뿐 아니라 무선 네트워크도 이용할 수 있다.');
INSERT INTO japanese_words(word,reading,meaning_ko,meaning_ja,jlpt_level_id,ai_status,note) SELECT s.word,s.reading,s.meaning_ko,s.meaning_ja,(SELECT id FROM jlpt_levels WHERE code='N1'),'reviewed','JLPT N1 batch 2027-02-04..2027-02-17' FROM _n1_b10_words_0125 s WHERE NOT EXISTS (SELECT 1 FROM japanese_words w WHERE w.word=s.word AND w.reading=s.reading AND w.deleted_at IS NULL);
INSERT INTO _n1_b10_map_0125(source_key,word_id) SELECT s.source_key,MIN(w.id) FROM _n1_b10_words_0125 s JOIN japanese_words w ON w.word=s.word AND w.reading=s.reading AND w.deleted_at IS NULL GROUP BY s.source_key;
