INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-04','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3848","prompt":"「明白」の読み方として最も適切なものを選びなさい。","options":["ほんき","はるか","いちぶ","あからさま"],"answer":"あからさま","explanationKo":"「明白」는 「あからさま」라고 읽는다. 뜻은 노골적; 공공연함; 숨김없음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-04','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3849","prompt":"「訪れる」の読み方として最も適切なものを選びなさい。","options":["といあわせる","ねばる","おとずれる","やくだつ"],"answer":"おとずれる","explanationKo":"「訪れる」는 「おとずれる」라고 읽는다. 뜻은 방문하다; 찾아오다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-04','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3850","prompt":"「決まる」の読み方として最も適切なものを選びなさい。","options":["きりかえる","きまる","はてる","くぐる"],"answer":"きまる","explanationKo":"「決まる」는 「きまる」라고 읽는다. 뜻은 정해지다; 결정되다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-04','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3841","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n定期検診のため、半年に一度は（　）を受診するようにしている。","options":["歯科","覚え","自己","現地"],"answer":"歯科","explanationKo":"문맥상 「歯科」가 가장 자연스럽다. 치과; 치의학라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-04','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3842","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの地域では（　）病院が救急医療の中心的な役割を担っている。","options":["職員","現像","保護","公立"],"answer":"公立","explanationKo":"문맥상 「公立」가 가장 자연스럽다. 공립; 지방자치단체가 설립·운영함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-04','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3843","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n大雪のため、午前中は（　）を見合わせるよう学校から連絡があった。","options":["一言","給食","登校","夕暮れ"],"answer":"登校","explanationKo":"문맥상 「登校」가 가장 자연스럽다. 등교; 학교에 감라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-04','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3844","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n高齢者が（　）する際は、急な温度変化に十分注意する必要がある。","options":["購入","入浴","無線","値引き"],"answer":"入浴","explanationKo":"문맥상 「入浴」가 가장 자연스럽다. 입욕; 목욕함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-04','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3845","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は宗教史を研究するため、複数の言語で（　）を読み比べている。","options":["聖書","晴天","一目","天国"],"answer":"聖書","explanationKo":"문맥상 「聖書」가 가장 자연스럽다. 성경; 성서라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-04','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3846","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n注意が必要な箇所は（　）で表示し、重大な警告は赤色で示している。","options":["大空","漁村","左利き","黄色"],"answer":"黄色","explanationKo":"문맥상 「黄色」가 가장 자연스럽다. 황색; 노란색라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-04','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3847","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n仲介業者を通さず、売り手と買い手が（　）で条件を決める取引もある。","options":["和文","情け","相対","一部分"],"answer":"相対","explanationKo":"문맥상 「相対」가 가장 자연스럽다. 당사자끼리 직접; 대면; 중개 없이라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-04','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3851","prompt":"「物事から喜び・面白さを感じ、味わう。」という意味に最も近い語を選びなさい。","options":["鍛える","楽しむ","早める","弱る"],"answer":"楽しむ","explanationKo":"「楽しむ」의 핵심 의미는 즐기다; 감상하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-04','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3852","prompt":"「ある状態・場所などが元に戻る。また、反応・結果が自分の側へ戻る。」という意味に最も近い語を選びなさい。","options":["返る","切り替える","突く","垂れる"],"answer":"返る","explanationKo":"「返る」의 핵심 의미는 돌아가다; 되돌아오다; 원상태가 되다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-04','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3853","prompt":"「人・物・情報・関心などが一つの場所・対象に寄る。」という意味に最も近い語を選びなさい。","options":["混む","決まる","間違う","集まる"],"answer":"集まる","explanationKo":"「集まる」의 핵심 의미는 모이다; 집중되다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-04','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3854","prompt":"「するべきことを終える。また、必要なことを簡単な方法で間に合わせる。」という意味に最も近い語を選びなさい。","options":["甘える","任す","済ます","殴る"],"answer":"済ます","explanationKo":"「済ます」의 핵심 의미는 끝내다; 마치다; 간단히 때우다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-04','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3855","prompt":"「指・くちばし・細い物などで、軽く何度も押したり刺したりする。」という意味に最も近い語を選びなさい。","options":["投げ出す","突く","抜かす","痛める"],"answer":"突く","explanationKo":"「突く」의 핵심 의미는 콕콕 찌르다; 쪼다; 건드리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-04','grammar',1,'〜あろうことか','{"pattern":"〜あろうことか","meaningKo":"놀랍게도; 있을 수 있게도","explanation":"〜あろうことか는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"あろうことか、担当者は原本を廃棄してしまった。","ko":"문맥에서 놀랍게도; 있을 수 있게도의 의미로 쓰였다."},{"ja":"あろうことか、警備員が鍵を持たずに巡回していた。","ko":"이 문장도 놀랍게도; 있을 수 있게도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-04','grammar',2,'〜いざ〜となると','{"pattern":"〜いざ〜となると","meaningKo":"막상 〜하려고 하면","explanation":"〜いざ〜となると는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"いざ説明するとなると、要点をまとめるのは難しい。","ko":"문맥에서 막상 〜하려고 하면의 의미로 쓰였다."},{"ja":"いざ出発となると、準備不足が次々に見つかった。","ko":"이 문장도 막상 〜하려고 하면의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-04','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n（　）、担当者は原本を廃棄してしまった。","options":["〜あろうことか","〜がましい","〜てみせる","〜に値する"],"answer":"〜あろうことか","explanationKo":"문맥상 놀랍게도; 있을 수 있게도를 나타내는 「〜あろうことか」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-04','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n（　）、要点をまとめるのは難しい。","options":["〜ぐるみ","〜とあってか","〜にあたらず","〜いざ〜となると"],"answer":"〜いざ〜となると","explanationKo":"문맥상 막상 〜하려고 하면를 나타내는 「〜いざ〜となると」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-04','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n毎日練習した（　）、決勝で敗れてしまった。","options":["〜とでもいうべき","〜にとどまる","〜かいもなく","〜だけましだ"],"answer":"〜かいもなく","explanationKo":"문맥상 〜한 보람도 없이를 나타내는 「〜かいもなく」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-04','reading',1,'公立施設の価値を利用者数だけで測らない','{"passage":"図書館や文化施設の成果を評価することには、資源配分の妥当性を説明しやすくなることという利点がある。ただし、来場者数だけでは少数者への支援や資料保存の価値が見えないことには注意しなければならない。単一の数字や事例だけで結論を固定せず、前提と影響を継続して検証する必要がある。したがって、複数の公共目的ごとに成果と利用機会を確かめることが重要なのである。","questions":[{"prompt":"「公立施設の価値を利用者数だけで測らない」について筆者が最も重視していることは何か。","options":["複数の公共目的ごとに成果と利用機会を確かめること","一つの数字だけで結論を固定すること","例外をすべて判断対象から外すこと","実施後の影響を確認しないこと"],"answer":"複数の公共目的ごとに成果と利用機会を確かめること","explanationKo":"본문에서는 複数の公共目的ごとに成果と利用機会を確かめること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["来場者数だけでは少数者への支援や資料保存の価値が見えないこと","前提を示すと比較が不可能になること","記録を残すと利点が失われること","複数の資料を使うと判断できなくなること"],"answer":"来場者数だけでは少数者への支援や資料保存の価値が見えないこと","explanationKo":"주의할 점은 来場者数だけでは少数者への支援や資料保存の価値が見えないこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["資源配分の妥当性を説明しやすくなること","単一の事例だけで方針を決めるべきだ","実施後の検証は不要である","影響を受ける人の違いは考慮しなくてよい"],"answer":"資源配分の妥当性を説明しやすくなること","explanationKo":"図書館や文化施設の成果を評価すること에는 資源配分の妥当性を説明しやすくなること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-05','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3868","prompt":"「仕立てる」の読み方として最も適切なものを選びなさい。","options":["したてる","ぬかす","とりよせる","なげだす"],"answer":"したてる","explanationKo":"「仕立てる」는 「したてる」라고 읽는다. 뜻은 짓다; 만들다; 재단하다; 길러내다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-05','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3869","prompt":"「鍛える」の読み方として最も適切なものを選びなさい。","options":["おいだす","はてる","くぐる","きたえる"],"answer":"きたえる","explanationKo":"「鍛える」는 「きたえる」라고 읽는다. 뜻은 단련하다; 훈련하다; 담금질하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-05','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3870","prompt":"「追い出す」の読み方として最も適切なものを選びなさい。","options":["やすめる","たもつ","おいだす","まちがう"],"answer":"おいだす","explanationKo":"「追い出す」는 「おいだす」라고 읽는다. 뜻은 쫓아내다; 몰아내다; 축출하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-05','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3861","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n画面を（　）にスクロールすると、すべての項目を確認できる。","options":["蛋白質","上下","真上","横綱"],"answer":"上下","explanationKo":"문맥상 「上下」가 가장 자연스럽다. 위아래; 상하라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-05','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3862","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は疲れ切った（　）で椅子に座り込んだ。","options":["体","三日月","縁談","覚え"],"answer":"体","explanationKo":"문맥상 「体」가 가장 자연스럽다. 모양; 태; 상태; 체재라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-05','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3863","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n忙しくて本を読む（　）もない。","options":["結び","施設","職員","暇"],"answer":"暇","explanationKo":"문맥상 「暇」가 가장 자연스럽다. 틈; 여가; 휴가; 작별라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-05','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3864","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n測定した（　）が基準を大きく超えたため、装置を停止して原因を調べた。","options":["合唱","帰京","値","一言"],"answer":"値","explanationKo":"문맥상 「値」가 가장 자연스럽다. 값; 가치; 수치라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-05','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3865","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）の上では春だが、山間部ではまだ雪が残っている。","options":["後悔","暦","日焼け","設置"],"answer":"暦","explanationKo":"문맥상 「暦」가 가장 자연스럽다. 달력; 역법라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-05','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3866","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n歴史あるホテルとしての（　）を保つため、接客の質にも厳しい基準を設けている。","options":["格","挑戦","脈","晴天"],"answer":"格","explanationKo":"문맥상 「格」가 가장 자연스럽다. 격; 품격; 지위·등급라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-05','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3867","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n川の曲がり角に大きな（　）ができていた。","options":["父母","大事","大空","渦"],"answer":"渦","explanationKo":"문맥상 「渦」가 가장 자연스럽다. 소용돌이; 소용돌이치는 상태라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-05','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3871","prompt":"「物に覆われて見えなくなる。また、周囲が物でいっぱいになる。」という意味に最も近い語を選びなさい。","options":["返る","割り込む","埋まる","訪れる"],"answer":"埋まる","explanationKo":"「埋まる」의 핵심 의미는 파묻히다; 가득 차다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-05','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3872","prompt":"「予定・時刻などをより早くする。」という意味に最も近い語を選びなさい。","options":["楽しむ","早める","返る","混む"],"answer":"早める","explanationKo":"「早める」의 핵심 의미는 앞당기다; 빨리하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-05','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3873","prompt":"「体・心などを傷つけ、痛みや苦しみを与える。」という意味に最も近い語を選びなさい。","options":["痛める","引き下げる","殴る","当てはめる"],"answer":"痛める","explanationKo":"「痛める」의 핵심 의미는 다치게 하다; 상하게 하다; 괴롭게 하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-05','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3874","prompt":"「品物・資料などを注文したり依頼したりして、別の場所から手元に届けさせる。」という意味に最も近い語を選びなさい。","options":["丸める","抜かす","痛める","取り寄せる"],"answer":"取り寄せる","explanationKo":"「取り寄せる」의 핵심 의미는 주문해서 받아오다; 다른 곳에서 가져오게 하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-05','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3875","prompt":"「物を丸い形にする、巻く。また、言葉巧みに人を自分の思い通りにする。」という意味に最も近い語を選びなさい。","options":["追い出す","果てる","丸める","仕立てる"],"answer":"丸める","explanationKo":"「丸める」의 핵심 의미는 둥글게 만들다; 말다; 뭉치다; 구슬리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-05','grammar',1,'〜かいもなく','{"pattern":"〜かいもなく","meaningKo":"〜한 보람도 없이","explanation":"〜かいもなく는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"長時間交渉したかいもなく、合意には至らなかった。","ko":"문맥에서 〜한 보람도 없이의 의미로 쓰였다."},{"ja":"毎日練習したかいもなく、決勝で敗れてしまった。","ko":"이 문장도 〜한 보람도 없이의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-05','grammar',2,'〜かいがあって','{"pattern":"〜かいがあって","meaningKo":"〜한 보람이 있어","explanation":"〜かいがあって는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"粘り強く説得したかいがあって、協力を得られた。","ko":"문맥에서 〜한 보람이 있어의 의미로 쓰였다."},{"ja":"調査を続けたかいがあって、原因を特定できた。","ko":"이 문장도 〜한 보람이 있어의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-05','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n長時間交渉した（　）、合意には至らなかった。","options":["〜だけましだ","〜とでもいうべき","〜にとどまる","〜かいもなく"],"answer":"〜かいもなく","explanationKo":"문맥상 〜한 보람도 없이를 나타내는 「〜かいもなく」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-05','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n粘り強く説得した（　）、協力を得られた。","options":["〜ないとも限らない","〜は別として","〜かいがあって","〜だの〜だの"],"answer":"〜かいがあって","explanationKo":"문맥상 〜한 보람이 있어를 나타내는 「〜かいがあって」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-05','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n選手たちは（　）競い合った。","options":["〜までもなく","〜かぎりを尽くす","〜た拍子に","〜なくはない"],"answer":"〜かぎりを尽くす","explanationKo":"문맥상 할 수 있는 모든 〜을 다하다를 나타내는 「〜かぎりを尽くす」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-05','reading',1,'専門語の読み分けを文脈で判断する','{"passage":"同じ表記を持つ語の意味と読みを理解することには、文章の分野と筆者の意図を正確に捉えられることという利点がある。ただし、最も身近な読みだけを当てはめると専門的な用法を誤ることには注意しなければならない。単一の数字や事例だけで結論を固定せず、前提と影響を継続して検証する必要がある。したがって、前後の共起語と文章の分野から読みと意味を確認することが重要なのである。","questions":[{"prompt":"「専門語の読み分けを文脈で判断する」について筆者が最も重視していることは何か。","options":["前後の共起語と文章の分野から読みと意味を確認すること","一つの数字だけで結論を固定すること","例外をすべて判断対象から外すこと","実施後の影響を確認しないこと"],"answer":"前後の共起語と文章の分野から読みと意味を確認すること","explanationKo":"본문에서는 前後の共起語と文章の分野から読みと意味を確認すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["最も身近な読みだけを当てはめると専門的な用法を誤ること","前提を示すと比較が不可能になること","記録を残すと利点が失われること","複数の資料を使うと判断できなくなること"],"answer":"最も身近な読みだけを当てはめると専門的な用法を誤ること","explanationKo":"주의할 점은 最も身近な読みだけを当てはめると専門的な用法を誤ること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["文章の分野と筆者の意図を正確に捉えられること","単一の事例だけで方針を決めるべきだ","実施後の検証は不要である","影響を受ける人の違いは考慮しなくてよい"],"answer":"文章の分野と筆者の意図を正確に捉えられること","explanationKo":"同じ表記を持つ語の意味と読みを理解すること에는 文章の分野と筆者の意図を正確に捉えられること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-06','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3888","prompt":"「抜かす」の読み方として最も適切なものを選びなさい。","options":["こむ","ぬかす","わりこむ","たのしむ"],"answer":"ぬかす","explanationKo":"「抜かす」는 「ぬかす」라고 읽는다. 뜻은 빼먹다; 생략하다; 건너뛰다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-06','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3889","prompt":"「当てはめる」の読み方として最も適切なものを選びなさい。","options":["あてはめる","たのしむ","まちがう","きまる"],"answer":"あてはめる","explanationKo":"「当てはめる」는 「あてはめる」라고 읽는다. 뜻은 적용하다; 맞춰 보다; 대입하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-06','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3890","prompt":"「粘る」の読み方として最も適切なものを選びなさい。","options":["ぬかす","とりよせる","なげだす","ねばる"],"answer":"ねばる","explanationKo":"「粘る」는 「ねばる」라고 읽는다. 뜻은 끈적거리다; 버티다; 끈기 있게 계속하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-06','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3881","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）に備えて、各家庭で飲料水と食料を備蓄することが推奨されている。","options":["渦","問屋","災害","箇所"],"answer":"災害","explanationKo":"문맥상 「災害」가 가장 자연스럽다. 재해; 재난라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-06','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3882","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n早期に（　）を発見するため、定期的に検診を受けている。","options":["真上","癌","音色","主食"],"answer":"癌","explanationKo":"문맥상 「癌」가 가장 자연스럽다. 암; 암종라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-06','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3883","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n医師が患者の（　）を取った。","options":["脈","家来","極楽","三日月"],"answer":"脈","explanationKo":"문맥상 「脈」가 가장 자연스럽다. 맥; 맥박; 가능성의 실마리라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-06','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3884","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの書類は人事部長（　）に送ってください。","options":["冷蔵","三日月","帰京","宛"],"answer":"宛","explanationKo":"문맥상 「宛」가 가장 자연스럽다. ~앞; 수신처; 대상라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-06','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3885","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n交渉では相手のほうが一枚（　）だった。","options":["眩しい","間もなく","上手","大げさ"],"answer":"上手","explanationKo":"문맥상 「上手」가 가장 자연스럽다. 한 수 위; 더 능숙한 사람; 고수라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-06','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3886","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n新しい作業は難しく感じるが、（　）れば短時間で処理できるようになる。","options":["日焼け","慣れ","内部","登校"],"answer":"慣れ","explanationKo":"문맥상 「慣れ」가 가장 자연스럽다. 익숙함; 숙련; 경험라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-06','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3887","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n変更内容の（　）は、後日ウェブサイトで公表される予定だ。","options":["詳細","明白","一部","爽やか"],"answer":"詳細","explanationKo":"문맥상 「詳細」가 가장 자연스럽다. 상세; 자세한 내용라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-06','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3891","prompt":"「我慢する時間が短く、すぐ怒ったり結論を急いだりする性質。」という意味に最も近い語を選びなさい。","options":["本気","明白","一部","短気"],"answer":"短気","explanationKo":"「短気」의 핵심 의미는 성급함; 다혈질이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-06','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3892","prompt":"「複数の人が声を合わせ、同じ曲または複数の声部を同時に歌うこと。」という意味に最も近い語を選びなさい。","options":["指示","渦","合唱","勝利"],"answer":"合唱","explanationKo":"「合唱」의 핵심 의미는 합창; 여러 사람이 함께 노래함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-06','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3893","prompt":"「音の高さ・長さ・強さなどを音符や記号で記したもの。」という意味に最も近い語を選びなさい。","options":["熱湯","楽譜","旦那","主人公"],"answer":"楽譜","explanationKo":"「楽譜」의 핵심 의미는 악보이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-06','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3894","prompt":"「上着・シャツ・ズボンなど、身につける服の総称。」という意味に最も近い語を選びなさい。","options":["衣類","油絵","縁側","行い"],"answer":"衣類","explanationKo":"「衣類」의 핵심 의미는 의류; 옷가지이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-06','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3895","prompt":"「額の小さい硬貨や、細かく使える少額の金。」という意味に最も近い語を選びなさい。","options":["遅れ","締め切り","軍事","小銭"],"answer":"小銭","explanationKo":"「小銭」의 핵심 의미는 잔돈; 동전이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-06','grammar',1,'〜かぎりを尽くす','{"pattern":"〜かぎりを尽くす","meaningKo":"할 수 있는 모든 〜을 다하다","explanation":"〜かぎりを尽くす는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"救助隊は力のかぎりを尽くして捜索を続けた。","ko":"문맥에서 할 수 있는 모든 〜을 다하다의 의미로 쓰였다."},{"ja":"選手たちは技のかぎりを尽くして競い合った。","ko":"이 문장도 할 수 있는 모든 〜을 다하다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-06','grammar',2,'〜がましい','{"pattern":"〜がましい","meaningKo":"〜스럽다; 〜한 티가 나다","explanation":"〜がましい는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"恩着せがましい言い方は、相手の負担になる。","ko":"문맥에서 〜스럽다; 〜한 티가 나다의 의미로 쓰였다."},{"ja":"未練がましい態度を改め、結果を受け入れた。","ko":"이 문장도 〜스럽다; 〜한 티가 나다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-06','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n救助隊は（　）捜索を続けた。","options":["〜なくはない","〜までもなく","〜かぎりを尽くす","〜た拍子に"],"answer":"〜かぎりを尽くす","explanationKo":"문맥상 할 수 있는 모든 〜을 다하다를 나타내는 「〜かぎりを尽くす」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-06','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n恩着せ（　）言い方は、相手の負担になる。","options":["〜も構わず","〜がましい","〜てでも","〜なくもない"],"answer":"〜がましい","explanationKo":"문맥상 〜스럽다; 〜한 티가 나다를 나타내는 「〜がましい」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-06','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n会社（　）の不正が調査で明らかになった。","options":["〜ぐるみ","〜てみせる","〜ならともかく","〜もそこそこに"],"answer":"〜ぐるみ","explanationKo":"문맥상 〜전체가 함께를 나타내는 「〜ぐるみ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-06','reading',1,'災害記録を日常の計画に戻す','{"passage":"過去の災害と対応を記録することには、次の危機に備えるための具体的な知識を残せることという利点がある。ただし、報告書を保存するだけでは平時の設備や訓練に反映されないことには注意しなければならない。単一の数字や事例だけで結論を固定せず、前提と影響を継続して検証する必要がある。したがって、記録から担当と期限のある改善項目を作ることが重要なのである。","questions":[{"prompt":"「災害記録を日常の計画に戻す」について筆者が最も重視していることは何か。","options":["記録から担当と期限のある改善項目を作ること","一つの数字だけで結論を固定すること","例外をすべて判断対象から外すこと","実施後の影響を確認しないこと"],"answer":"記録から担当と期限のある改善項目を作ること","explanationKo":"본문에서는 記録から担当と期限のある改善項目を作ること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["報告書を保存するだけでは平時の設備や訓練に反映されないこと","前提を示すと比較が不可能になること","記録を残すと利点が失われること","複数の資料を使うと判断できなくなること"],"answer":"報告書を保存するだけでは平時の設備や訓練に反映されないこと","explanationKo":"주의할 점은 報告書を保存するだけでは平時の設備や訓練に反映されないこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["次の危機に備えるための具体的な知識を残せること","単一の事例だけで方針を決めるべきだ","実施後の検証は不要である","影響を受ける人の違いは考慮しなくてよい"],"answer":"次の危機に備えるための具体的な知識を残せること","explanationKo":"過去の災害と対応を記録すること에는 次の危機に備えるための具体的な知識を残せること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-07','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3901","prompt":"「一息」の読み方として最も適切なものを選びなさい。","options":["いっぱい","おおみず","ひといき","はまべ"],"answer":"ひといき","explanationKo":"「一息」는 「ひといき」라고 읽는다. 뜻은 한숨; 잠깐의 휴식; 한 번에이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-07','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3902","prompt":"「神殿」の読み方として最も適切なものを選びなさい。","options":["すすめ","しんでん","たんか","かんご"],"answer":"しんでん","explanationKo":"「神殿」는 「しんでん」라고 읽는다. 뜻은 신전이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
