INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-07','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3906","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの地域には昔から織物を扱う（　）が多かった。","options":["神殿","問屋","体験","値"],"answer":"問屋","explanationKo":"문맥상 「問屋」가 가장 자연스럽다. 도매상; 도매점라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-07','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3907","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n大型（　）には高速道路や観光地の混雑が予想される。","options":["連休","年長","星座","家来"],"answer":"連休","explanationKo":"문맥상 「連休」가 가장 자연스럽다. 연휴라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-07','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3908","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n大会当日は（　）に恵まれ、予定どおりすべての競技が行われた。","options":["悪者","警部","短波","晴天"],"answer":"晴天","explanationKo":"문맥상 「晴天」가 가장 자연스럽다. 맑은 날씨; 청명한 하늘라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-07','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3909","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）試験の結果は来週オンラインで発表される。","options":["使用人","助け","期末","花壇"],"answer":"期末","explanationKo":"문맥상 「期末」가 가장 자연스럽다. 기말; 기간의 끝라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-07','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3910","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n学校では栄養バランスを考えた（　）が毎日提供されている。","options":["従業員","給食","用法","水気"],"answer":"給食","explanationKo":"문맥상 「給食」가 가장 자연스럽다. 급식라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-07','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3911","prompt":"「学問と芸術。また、それらに関する知識・技能。」という意味に最も近い語を選びなさい。","options":["学芸","美術","読者","採用"],"answer":"学芸","explanationKo":"「学芸」의 핵심 의미는 학예; 학문과 예술이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-07','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3912","prompt":"「演劇を継続的に制作・上演する人々の団体。」という意味に最も近い語を選びなさい。","options":["修学","治療","同士","劇団"],"answer":"劇団","explanationKo":"「劇団」의 핵심 의미는 극단이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-07','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3913","prompt":"「笑いを中心に、人間や社会を明るく・風刺的に描く演劇・作品。」という意味に最も近い語を選びなさい。","options":["暇","一息","喜劇","戦闘"],"answer":"喜劇","explanationKo":"「喜劇」의 핵심 의미는 희극; 코미디이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-07','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3914","prompt":"「複数の建物のうち、中心となる主要な建物。」という意味に最も近い語を選びなさい。","options":["旦那","本館","満月","利息"],"answer":"本館","explanationKo":"「本館」의 핵심 의미는 본관; 주 건물이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-07','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3915","prompt":"「腸の働きが乱れ、水分の多い便を何度も排出する症状。」という意味に最も近い語を選びなさい。","options":["下痢","上下","満月","役場"],"answer":"下痢","explanationKo":"「下痢」의 핵심 의미는 설사이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-07','grammar',1,'〜ぐるみ','{"pattern":"〜ぐるみ","meaningKo":"〜전체가 함께","explanation":"〜ぐるみ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"地域ぐるみで高齢者の見守りに取り組んでいる。","ko":"문맥에서 〜전체가 함께의 의미로 쓰였다."},{"ja":"会社ぐるみの不正が調査で明らかになった。","ko":"이 문장도 〜전체가 함께의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-07','grammar',2,'〜だけましだ','{"pattern":"〜だけましだ","meaningKo":"그나마 〜인 편이 낫다","explanation":"〜だけましだ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"遅れても連絡があっただけましだ。","ko":"문맥에서 그나마 〜인 편이 낫다의 의미로 쓰였다."},{"ja":"被害が建物だけで済んだだけましだと考えるしかない。","ko":"이 문장도 그나마 〜인 편이 낫다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-07','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n地域（　）で高齢者の見守りに取り組んでいる。","options":["〜もそこそこに","〜ぐるみ","〜てみせる","〜ならともかく"],"answer":"〜ぐるみ","explanationKo":"문맥상 〜전체가 함께를 나타내는 「〜ぐるみ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-07','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n遅れても連絡があった（　）。","options":["〜だけましだ","〜とあってか","〜ならともあれ","〜ようでは"],"answer":"〜だけましだ","explanationKo":"문맥상 그나마 〜인 편이 낫다를 나타내는 「〜だけましだ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-07','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n（　）を運ぶだけで午前中が終わった。","options":["〜とでもいうべき","〜に値する","〜を差し置いて","〜だの〜だの"],"answer":"〜だの〜だの","explanationKo":"문맥상 〜라느니 〜라느니를 나타내는 「〜だの〜だの」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-07','reading',1,'利子と将来費用を比較する','{"passage":"長期の事業で現在と将来の費用を見積もることには、異なる時期の選択肢を共通の基準で検討できることという利点がある。ただし、割引率の置き方だけで結論が大きく変わることには注意しなければならない。単一の数字や事例だけで結論を固定せず、前提と影響を継続して検証する必要がある。したがって、複数の前提で結果を示し判断の幅を明らかにすることが重要なのである。","questions":[{"prompt":"「利子と将来費用を比較する」について筆者が最も重視していることは何か。","options":["複数の前提で結果を示し判断の幅を明らかにすること","一つの数字だけで結論を固定すること","例外をすべて判断対象から外すこと","実施後の影響を確認しないこと"],"answer":"複数の前提で結果を示し判断の幅を明らかにすること","explanationKo":"본문에서는 複数の前提で結果を示し判断の幅を明らかにすること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["割引率の置き方だけで結論が大きく変わること","前提を示すと比較が不可能になること","記録を残すと利点が失われること","複数の資料を使うと判断できなくなること"],"answer":"割引率の置き方だけで結論が大きく変わること","explanationKo":"주의할 점은 割引率の置き方だけで結論が大きく変わること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["異なる時期の選択肢を共通の基準で検討できること","単一の事例だけで方針を決めるべきだ","実施後の検証は不要である","影響を受ける人の違いは考慮しなくてよい"],"answer":"異なる時期の選択肢を共通の基準で検討できること","explanationKo":"長期の事業で現在と将来の費用を見積もること에는 異なる時期の選択肢を共通の基準で検討できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-08','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3921","prompt":"「母校」の読み方として最も適切なものを選びなさい。","options":["こてい","てい","としごろ","ぼこう"],"answer":"ぼこう","explanationKo":"「母校」는 「ぼこう」라고 읽는다. 뜻은 모교이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
