INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-08','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3928","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n今年はこの色が（　）らしい。","options":["流行","手配","上下","年長"],"answer":"流行","explanationKo":"문맥상 「流行」가 가장 자연스럽다. 유행; 유행하는 것라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-08','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3929","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nその店は（　）の客でも丁寧に迎えてくれた。","options":["利子","本館","悪者","一見"],"answer":"一見","explanationKo":"문맥상 「一見」가 가장 자연스럽다. 초면; 처음 방문함; 낯선 손님라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-08','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3930","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nその作品を（　）見て、強く心を引かれた。","options":["教職","花壇","一目","元年"],"answer":"一目","explanationKo":"문맥상 「一目」가 가장 자연스럽다. 한눈; 한번 봄; 일견라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-08','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3931","prompt":"「文学・芸術などで作られた作品。」という意味に最も近い語を選びなさい。","options":["扱い","作物","共学","使い道"],"answer":"作物","explanationKo":"「作物」의 핵심 의미는 작품; 저작물이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-08','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3932","prompt":"「風を受けて羽根が回る玩具。また、風力を利用する装置を指すこともある。」という意味に最も近い語を選びなさい。","options":["風車","三味線","驚き","美術"],"answer":"風車","explanationKo":"「風車」의 핵심 의미는 바람개비; 풍차이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-08','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3933","prompt":"「新しい年号・時代などの最初の年。また比喩的に、新しい取り組みが本格的に始まった年。」という意味に最も近い語を選びなさい。","options":["距離","燃料","修学","元年"],"answer":"元年","explanationKo":"「元年」의 핵심 의미는 원년; 연호의 첫해이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-08','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3934","prompt":"「日光が当たって明るく暖かい場所。」という意味に最も近い語を選びなさい。","options":["選挙","戦闘","日向","教習"],"answer":"日向","explanationKo":"「日向」의 핵심 의미는 양지; 햇볕 드는 곳이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-08','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3935","prompt":"「柔道・剣道・空手などの武道や芸事を稽古する場所。」という意味に最も近い語を選びなさい。","options":["満月","道場","登録","相対"],"answer":"道場","explanationKo":"「道場」의 핵심 의미는 도장; 무예 수련장이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-08','grammar',1,'〜だの〜だの','{"pattern":"〜だの〜だの","meaningKo":"〜라느니 〜라느니","explanation":"〜だの〜だの는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"費用が高いだの時間がないだの、彼は言い訳ばかりする。","ko":"문맥에서 〜라느니 〜라느니의 의미로 쓰였다."},{"ja":"資料だの機材だのを運ぶだけで午前中が終わった。","ko":"이 문장도 〜라느니 〜라느니의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-08','grammar',2,'〜た拍子に','{"pattern":"〜た拍子に","meaningKo":"〜한 순간에; 〜한 바람에","explanation":"〜た拍子に는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"立ち上がった拍子に、机の角に膝をぶつけた。","ko":"문맥에서 〜한 순간에; 〜한 바람에의 의미로 쓰였다."},{"ja":"振り向いた拍子に、持っていた書類を落とした。","ko":"이 문장도 〜한 순간에; 〜한 바람에의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-08','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n（　）、彼は言い訳ばかりする。","options":["〜だの〜だの","〜とでもいうべき","〜に値する","〜を差し置いて"],"answer":"〜だの〜だの","explanationKo":"문맥상 〜라느니 〜라느니를 나타내는 「〜だの〜だの」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-08','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n立ち上がっ（　）、机の角に膝をぶつけた。","options":["〜ないとも限らない","〜にあたらず","〜あろうことか","〜た拍子に"],"answer":"〜た拍子に","explanationKo":"문맥상 〜한 순간에; 〜한 바람에를 나타내는 「〜た拍子に」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-08','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n徹夜し（　）、明日の期限には間に合わせる。","options":["〜にとどまる","〜いざ〜となると","〜てでも","〜なくはない"],"answer":"〜てでも","explanationKo":"문맥상 〜해서라도를 나타내는 「〜てでも」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-08','reading',1,'地域文化を展示物に固定しない','{"passage":"地域の歴史や芸能を保存し紹介することには、世代を越えて知識と経験を共有できることという利点がある。ただし、過去の形だけを正統とすると現在の担い手の変化を否定することには注意しなければならない。単一の数字や事例だけで結論を固定せず、前提と影響を継続して検証する必要がある。したがって、継承される要素と変化してきた過程をともに示すことが重要なのである。","questions":[{"prompt":"「地域文化を展示物に固定しない」について筆者が最も重視していることは何か。","options":["継承される要素と変化してきた過程をともに示すこと","一つの数字だけで結論を固定すること","例外をすべて判断対象から外すこと","実施後の影響を確認しないこと"],"answer":"継承される要素と変化してきた過程をともに示すこと","explanationKo":"본문에서는 継承される要素と変化してきた過程をともに示すこと 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["過去の形だけを正統とすると現在の担い手の変化を否定すること","前提を示すと比較が不可能になること","記録を残すと利点が失われること","複数の資料を使うと判断できなくなること"],"answer":"過去の形だけを正統とすると現在の担い手の変化を否定すること","explanationKo":"주의할 점은 過去の形だけを正統とすると現在の担い手の変化を否定すること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["世代を越えて知識と経験を共有できること","単一の事例だけで方針を決めるべきだ","実施後の検証は不要である","影響を受ける人の違いは考慮しなくてよい"],"answer":"世代を越えて知識と経験を共有できること","explanationKo":"地域の歴史や芸能を保存し紹介すること에는 世代を越えて知識と経験を共有できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-09','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3941","prompt":"「家主」の読み方として最も適切なものを選びなさい。","options":["いえぬし","しきん","てんさい","せいかい"],"answer":"いえぬし","explanationKo":"「家主」는 「いえぬし」라고 읽는다. 뜻은 집주인; 가옥의 소유자이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-09','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3942","prompt":"「裸足」の読み方として最も適切なものを選びなさい。","options":["きっさ","ていきょう","こてい","はだし"],"answer":"はだし","explanationKo":"「裸足」는 「はだし」라고 읽는다. 뜻은 맨발이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-09','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3943","prompt":"「真上」の読み方として最も適切なものを選びなさい。","options":["おうしょく","がっぴ","まうえ","よそう"],"answer":"まうえ","explanationKo":"「真上」는 「まうえ」라고 읽는다. 뜻은 바로 위; 정수리 위쪽이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-09','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3944","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼とは高校で（　）だったが、卒業後は別の道に進んだ。","options":["元年","同級","衣類","劇団"],"answer":"同級","explanationKo":"문맥상 「同級」가 가장 자연스럽다. 동급; 같은 학년·등급라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-09','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3945","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n免許を取るため、自動車学校で運転（　）を受けている。","options":["教習","公立","衣類","劇団"],"answer":"教習","explanationKo":"문맥상 「教習」가 가장 자연스럽다. 교습; 실기 교육라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-09','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3946","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n鳥の群れが（　）をゆっくり横切っていった。","options":["式場","後回し","香辛料","大空"],"answer":"大空","explanationKo":"문맥상 「大空」가 가장 자연스럽다. 넓은 하늘; 창공라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-09','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3947","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n旅行ではホテルではなく、地元の（　）に泊まった。","options":["申し込み","保険","民宿","軍服"],"answer":"民宿","explanationKo":"문맥상 「民宿」가 가장 자연스럽다. 민박; 민박집라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-09','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3948","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの素材は（　）できないため、専用の方法で手入れする必要がある。","options":["情け","水洗","一部分","和文"],"answer":"水洗","explanationKo":"문맥상 「水洗」가 가장 자연스럽다. 물로 씻음; 수세식라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-09','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3949","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n山では天候が変わりやすいので、必ず（　）を持参してください。","options":["雨具","現像","保護","手配"],"answer":"雨具","explanationKo":"문맥상 「雨具」가 가장 자연스럽다. 우비; 비를 막는 장비라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-09','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3950","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n温泉好きの彼にとって、各地の温泉を自由に巡れるこの町はまさに（　）だ。","options":["開催","聖書","利子","天国"],"answer":"天国","explanationKo":"문맥상 「天国」가 가장 자연스럽다. 천국; 천당; 낙원 같은 곳라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-09','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3951","prompt":"「競技・大会で優勝者や最終的な勝者を決める最後の試合・段階。」という意味に最も近い語を選びなさい。","options":["学芸","風車","決勝","楽譜"],"answer":"決勝","explanationKo":"「決勝」의 핵심 의미는 결승; 결승전이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-09','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3952","prompt":"「問題・質問に対する正しい答え。また、判断・選択として適切なことを比喩的にいう場合もある。」という意味に最も近い語を選びなさい。","options":["学芸","正解","歯科","楽譜"],"answer":"正解","explanationKo":"「正解」의 핵심 의미는 정답; 올바른 해답이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-09','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3953","prompt":"「他からの動作を受ける文法形式。また、自分から積極的に動かない態度。」という意味に最も近い語を選びなさい。","options":["受身","物好き","上手","平たい"],"answer":"受身","explanationKo":"「受身」의 핵심 의미는 수동; 수동태; 수세적인 태도이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-09','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3954","prompt":"「学問や技術などを学び修めること。」という意味に最も近い語を選びなさい。","options":["同級","海路","味わい","修学"],"answer":"修学","explanationKo":"「修学」의 핵심 의미는 수학; 학문을 배움이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-09','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3955","prompt":"「物や語句などの使い方。」という意味に最も近い語を選びなさい。","options":["上司","教習","用法","現場"],"answer":"用法","explanationKo":"「用法」의 핵심 의미는 용법; 사용법이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-09','grammar',1,'〜てでも','{"pattern":"〜てでも","meaningKo":"〜해서라도","explanation":"〜てでも는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"多少費用がかかってでも、安全性を優先すべきだ。","ko":"문맥에서 〜해서라도의 의미로 쓰였다."},{"ja":"徹夜してでも、明日の期限には間に合わせる。","ko":"이 문장도 〜해서라도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-09','grammar',2,'〜てみせる','{"pattern":"〜てみせる","meaningKo":"반드시 〜해 보이겠다","explanation":"〜てみせる는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"困難な条件でも、必ず計画を実現してみせる。","ko":"문맥에서 반드시 〜해 보이겠다의 의미로 쓰였다."},{"ja":"次の試合では自分の力を証明してみせる。","ko":"이 문장도 반드시 〜해 보이겠다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-09','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n多少費用がかかっ（　）、安全性を優先すべきだ。","options":["〜なくはない","〜にとどまる","〜いざ〜となると","〜てでも"],"answer":"〜てでも","explanationKo":"문맥상 〜해서라도를 나타내는 「〜てでも」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-09','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n困難な条件でも、必ず計画を実現し（　）。","options":["〜は別として","〜かいもなく","〜てみせる","〜なくもない"],"answer":"〜てみせる","explanationKo":"문맥상 반드시 〜해 보이겠다를 나타내는 「〜てみせる」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-09','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n人気作家の新刊（　）、発売前から注文が相次いだ。","options":["〜かいがあって","〜とあってか","〜ならともかく","〜までもなく"],"answer":"〜とあってか","explanationKo":"문맥상 〜여서인지를 나타내는 「〜とあってか」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-09','reading',1,'用法の変化を誤りと決めつけない','{"passage":"言葉の新しい使われ方を調査することには、社会や媒体の変化を言語から読み取れることという利点がある。ただし、従来の規範だけで判断すると実際の意味変化を見落とすことには注意しなければならない。単一の数字や事例だけで結論を固定せず、前提と影響を継続して検証する必要がある。したがって、年代と場面と話者集団を分けて用例を比較することが重要なのである。","questions":[{"prompt":"「用法の変化を誤りと決めつけない」について筆者が最も重視していることは何か。","options":["年代と場面と話者集団を分けて用例を比較すること","一つの数字だけで結論を固定すること","例外をすべて判断対象から外すこと","実施後の影響を確認しないこと"],"answer":"年代と場面と話者集団を分けて用例を比較すること","explanationKo":"본문에서는 年代と場面と話者集団を分けて用例を比較すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["従来の規範だけで判断すると実際の意味変化を見落とすこと","前提を示すと比較が不可能になること","記録を残すと利点が失われること","複数の資料を使うと判断できなくなること"],"answer":"従来の規範だけで判断すると実際の意味変化を見落とすこと","explanationKo":"주의할 점은 従来の規範だけで判断すると実際の意味変化を見落とすこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["社会や媒体の変化を言語から読み取れること","単一の事例だけで方針を決めるべきだ","実施後の検証は不要である","影響を受ける人の違いは考慮しなくてよい"],"answer":"社会や媒体の変化を言語から読み取れること","explanationKo":"言葉の新しい使われ方を調査すること에는 社会や媒体の変化を言語から読み取れること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-10','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3961","prompt":"「主人公」の読み方として最も適切なものを選びなさい。","options":["かんれき","しゅじんこう","うみじ","あじわい"],"answer":"しゅじんこう","explanationKo":"「主人公」는 「しゅじんこう」라고 읽는다. 뜻은 주인공; 중심인물이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
