INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-10','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3967","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼はついに（　）へ昇進した。","options":["大事","大空","式場","横綱"],"answer":"横綱","explanationKo":"문맥상 「横綱」가 가장 자연스럽다. 요코즈나; 스모 최고 등급의 선수라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-10','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3968","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n一行は（　）で島へ向かった。","options":["蛋白質","軍服","海路","特技"],"answer":"海路","explanationKo":"문맥상 「海路」가 가장 자연스럽다. 바닷길; 해로라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-10','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3969","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nその小さな（　）は新鮮な魚で有名だ。","options":["自己","漁村","縁談","覚え"],"answer":"漁村","explanationKo":"문맥상 「漁村」가 가장 자연스럽다. 어촌; 어촌 마을라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
