INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-10','grammar',1,'〜とあってか','{"pattern":"〜とあってか","meaningKo":"〜여서인지","explanation":"〜とあってか는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"連休初日とあってか、駅は朝から混雑している。","ko":"문맥에서 〜여서인지의 의미로 쓰였다."},{"ja":"人気作家の新刊とあってか、発売前から注文が相次いだ。","ko":"이 문장도 〜여서인지의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-10','grammar',2,'〜とでもいうべき','{"pattern":"〜とでもいうべき","meaningKo":"그야말로 〜라고 해야 할","explanation":"〜とでもいうべき는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"この発見は偶然の奇跡とでもいうべき成果だ。","ko":"문맥에서 그야말로 〜라고 해야 할의 의미로 쓰였다."},{"ja":"彼の判断は経験の結晶とでもいうべきものだ。","ko":"이 문장도 그야말로 〜라고 해야 할의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
