INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-10','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこの発見は偶然の奇跡（　）成果だ。","options":["〜かぎりを尽くす","〜とでもいうべき","〜ならともあれ","〜も構わず"],"answer":"〜とでもいうべき","explanationKo":"문맥상 그야말로 〜라고 해야 할를 나타내는 「〜とでもいうべき」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-10','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n安全装置が故障し（　）ため、点検が必要だ。","options":["〜ないとも限らない","〜に値する","〜もそこそこに","〜がましい"],"answer":"〜ないとも限らない","explanationKo":"문맥상 반드시 〜하지 않는다고 할 수 없다를 나타내는 「〜ないとも限らない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-10','reading',1,'現場の裁量と記録を両立する','{"passage":"担当者が状況に応じて判断できるようにすることには、例外的な事態へ迅速に対応できることという利点がある。ただし、裁量の理由が残らなければ一貫性と説明責任を失うことには注意しなければならない。単一の数字や事例だけで結論を固定せず、前提と影響を継続して検証する必要がある。したがって、判断の根拠と結果を後から検証できる形で残すことが重要なのである。","questions":[{"prompt":"「現場の裁量と記録を両立する」について筆者が最も重視していることは何か。","options":["判断の根拠と結果を後から検証できる形で残すこと","一つの数字だけで結論を固定すること","例外をすべて判断対象から外すこと","実施後の影響を確認しないこと"],"answer":"判断の根拠と結果を後から検証できる形で残すこと","explanationKo":"본문에서는 判断の根拠と結果を後から検証できる形で残すこと 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["裁量の理由が残らなければ一貫性と説明責任を失うこと","前提を示すと比較が不可能になること","記録を残すと利点が失われること","複数の資料を使うと判断できなくなること"],"answer":"裁量の理由が残らなければ一貫性と説明責任を失うこと","explanationKo":"주의할 점은 裁量の理由が残らなければ一貫性と説明責任を失うこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["例外的な事態へ迅速に対応できること","単一の事例だけで方針を決めるべきだ","実施後の検証は不要である","影響を受ける人の違いは考慮しなくてよい"],"answer":"例外的な事態へ迅速に対応できること","explanationKo":"担当者が状況に応じて判断できるようにすること에는 例外的な事態へ迅速に対応できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-11','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3981","prompt":"「三日月」の読み方として最も適切なものを選びなさい。","options":["といや","はやり","みかづき","さいがい"],"answer":"みかづき","explanationKo":"「三日月」는 「みかづき」라고 읽는다. 뜻은 초승달; 가느다란 초승달 모양의 달이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-11','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3982","prompt":"「貝殻」の読み方として最も適切なものを選びなさい。","options":["よこづな","かいがら","しゅしょく","まうえ"],"answer":"かいがら","explanationKo":"「貝殻」는 「かいがら」라고 읽는다. 뜻은 조개껍데기; 조가비이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-11','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3983","prompt":"「一部分」の読み方として最も適切なものを選びなさい。","options":["いちぶぶん","ごくらく","みかづき","じこくひょう"],"answer":"いちぶぶん","explanationKo":"「一部分」는 「いちぶぶん」라고 읽는다. 뜻은 일부분; 일부이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-11','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3984","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n肉や豆類には（　）が多く含まれる。","options":["碁盤","恐れ","殺人","蛋白質"],"answer":"蛋白質","explanationKo":"문맥상 「蛋白質」가 가장 자연스럽다. 단백질라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-11','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3985","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は現地の法律事情に（　）ため、海外案件の相談役を務めている。","options":["爽やか","不明","明るい","詳細"],"answer":"明るい","explanationKo":"문맥상 「明るい」가 가장 자연스럽다. 밝다; 전망이 좋다; ~에 정통하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-11','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3986","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n過去の障害記録は、同じ問題が再発したときの原因分析に（　）。","options":["集まる","役立つ","済ます","垂れる"],"answer":"役立つ","explanationKo":"문맥상 「役立つ」가 가장 자연스럽다. 도움이 되다; 유용하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-11','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3987","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n小さな失敗を必要以上に（　）に扱うべきではない。","options":["大げさ","日々","未婚","物好き"],"answer":"大げさ","explanationKo":"문맥상 「大げさ」가 가장 자연스럽다. 과장됨; 유난스러움라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-11','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3988","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n同じ失敗を原因も調べず繰り返すのは（　）なことだ。","options":["短気","日々","未婚","愚か"],"answer":"愚か","explanationKo":"문맥상 「愚か」가 가장 자연스럽다. 어리석다; 미련하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-11','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3989","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n細かな実装方法は担当者に（　）ことにした。","options":["弱る","早める","任す","痛める"],"answer":"任す","explanationKo":"문맥상 「任す」가 가장 자연스럽다. 맡기다; 일임하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-11','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3990","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n秋になると山々が（　）な赤や黄色に染まる。","options":["短気","鮮やか","一部","爽やか"],"answer":"鮮やか","explanationKo":"문맥상 「鮮やか」가 가장 자연스럽다. 선명함; 산뜻함; 훌륭함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-11','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3991","prompt":"「手・こぶし、または手に持った物で相手を強く打つ。」という意味に最も近い語を選びなさい。","options":["殴る","割り込む","楽しむ","混む"],"answer":"殴る","explanationKo":"「殴る」의 핵심 의미는 때리다; 주먹으로 치다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-11','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3992","prompt":"「普通の人なら関心を持たないような珍しいことを好んですること。また、その人。」という意味に最も近い語を選びなさい。","options":["本気","明白","一部","物好き"],"answer":"物好き","explanationKo":"「物好き」의 핵심 의미는 별난 것에 흥미를 보임; 그런 사람이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-11','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3993","prompt":"「試験・審査・検査などに合格する。」という意味に最も近い語を選びなさい。","options":["取り寄せる","投げ出す","受かる","抜かす"],"answer":"受かる","explanationKo":"「受かる」의 핵심 의미는 합격하다; 통과하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-11','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3994","prompt":"「人を選んで雇うこと。また、意見や方法などを取り上げて用いること。」という意味に最も近い語を選びなさい。","options":["専用","採用","反応","英雄"],"answer":"採用","explanationKo":"「採用」의 핵심 의미는 채용; 채택이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-11','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3995","prompt":"「特定の人・目的・用途だけに使うこと。」という意味に最も近い語を選びなさい。","options":["専用","修学","参照","恋愛"],"answer":"専用","explanationKo":"「専用」의 핵심 의미는 전용이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-11','grammar',1,'〜ないとも限らない','{"pattern":"〜ないとも限らない","meaningKo":"반드시 〜하지 않는다고 할 수 없다","explanation":"〜ないとも限らない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"小さな誤解が大きな対立に発展しないとも限らない。","ko":"문맥에서 반드시 〜하지 않는다고 할 수 없다의 의미로 쓰였다."},{"ja":"安全装置が故障しないとも限らないため、点検が必要だ。","ko":"이 문장도 반드시 〜하지 않는다고 할 수 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-11','grammar',2,'〜なくはない','{"pattern":"〜なくはない","meaningKo":"전혀 〜하지 않는 것은 아니다","explanation":"〜なくはない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"条件を調整すれば、参加できなくはない。","ko":"문맥에서 전혀 〜하지 않는 것은 아니다의 의미로 쓰였다."},{"ja":"その説明も理解できなくはないが、根拠が不足している。","ko":"이 문장도 전혀 〜하지 않는 것은 아니다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-11','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n小さな誤解が大きな対立に発展し（　）。","options":["〜がましい","〜ないとも限らない","〜に値する","〜もそこそこに"],"answer":"〜ないとも限らない","explanationKo":"문맥상 반드시 〜하지 않는다고 할 수 없다를 나타내는 「〜ないとも限らない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-11','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n条件を調整すれば、参加でき（　）。","options":["〜なくはない","〜にあたらず","〜ようでは","〜ぐるみ"],"answer":"〜なくはない","explanationKo":"문맥상 전혀 〜하지 않는 것은 아니다를 나타내는 「〜なくはない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-11','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n時間を延ばせば、今日中に完成でき（　）。","options":["〜にとどまる","〜を差し置いて","〜だけましだ","〜なくもない"],"answer":"〜なくもない","explanationKo":"문맥상 전혀 〜하지 않은 것도 아니다를 나타내는 「〜なくもない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-11','reading',1,'保護の名で当事者を排除しない','{"passage":"危険を減らすために利用や参加を制限することには、事故や損失を未然に防げることという利点がある。ただし、本人の意見を聞かない制限は自立の機会まで奪うことには注意しなければならない。単一の数字や事例だけで結論を固定せず、前提と影響を継続して検証する必要がある。したがって、危険の程度と本人の選択を確認して代替手段を用意することが重要なのである。","questions":[{"prompt":"「保護の名で当事者を排除しない」について筆者が最も重視していることは何か。","options":["危険の程度と本人の選択を確認して代替手段を用意すること","一つの数字だけで結論を固定すること","例外をすべて判断対象から外すこと","実施後の影響を確認しないこと"],"answer":"危険の程度と本人の選択を確認して代替手段を用意すること","explanationKo":"본문에서는 危険の程度と本人の選択を確認して代替手段を用意すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["本人の意見を聞かない制限は自立の機会まで奪うこと","前提を示すと比較が不可能になること","記録を残すと利点が失われること","複数の資料を使うと判断できなくなること"],"answer":"本人の意見を聞かない制限は自立の機会まで奪うこと","explanationKo":"주의할 점은 本人の意見を聞かない制限は自立の機会まで奪うこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["事故や損失を未然に防げること","単一の事例だけで方針を決めるべきだ","実施後の検証は不要である","影響を受ける人の違いは考慮しなくてよい"],"answer":"事故や損失を未然に防げること","explanationKo":"危険を減らすために利用や参加を制限すること에는 事故や損失を未然に防げること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-12','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4001","prompt":"「後回し」の読み方として最も適切なものを選びなさい。","options":["むせん","ちょうり","こうかい","あとまわし"],"answer":"あとまわし","explanationKo":"「後回し」는 「あとまわし」라고 읽는다. 뜻은 뒤로 미룸; 뒷전이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-12','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4002","prompt":"「前置き」の読み方として最も適切なものを選びなさい。","options":["りょうかい","さいがい","まえおき","せってい"],"answer":"まえおき","explanationKo":"「前置き」는 「まえおき」라고 읽는다. 뜻은 서두; 본론 전에 하는 말이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-12','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4003","prompt":"「無駄遣い」の読み方として最も適切なものを選びなさい。","options":["ちょうせん","むだづかい","せいかい","ちりょう"],"answer":"むだづかい","explanationKo":"「無駄遣い」는 「むだづかい」라고 읽는다. 뜻은 낭비; 헛씀이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-12','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-4004","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n助成金の（　）について、具体的な計画書を提出する必要がある。","options":["使い道","星座","家来","極楽"],"answer":"使い道","explanationKo":"문맥상 「使い道」가 가장 자연스럽다. 용도; 쓰임새라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
