INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-12','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-4006","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの会社では約五百人の（　）が働いている。","options":["勧め","共働き","従業員","漢語"],"answer":"従業員","explanationKo":"문맥상 「従業員」가 가장 자연스럽다. 종업원; 직원; 근로자라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-12','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-4007","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n出張を終え、明日の朝に（　）する予定だ。","options":["助け","帰京","花壇","使用人"],"answer":"帰京","explanationKo":"문맥상 「帰京」가 가장 자연스럽다. 도쿄로 돌아감; 귀경(도쿄 귀환)라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-12','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-4008","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n昔、その屋敷には多くの（　）がいた。","options":["使用人","天井","専用","同意"],"answer":"使用人","explanationKo":"문맥상 「使用人」가 가장 자연스럽다. 고용인; 사용인; 피고용인라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-12','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-4009","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n『文化』や『経済』は（　）の例として挙げられる。","options":["参照","箇所","渦","漢語"],"answer":"漢語","explanationKo":"문맥상 「漢語」가 가장 자연스럽다. 한어; 한자어; 일본어의 한자계 어휘라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-12','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-4010","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n祖母は（　）に座って庭を眺めていた。","options":["神殿","本場","縁側","値"],"answer":"縁側","explanationKo":"문맥상 「縁側」가 가장 자연스럽다. 툇마루; 일본식 집의 가장자리 마루라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-12','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4011","prompt":"「船の乗り降りや荷物の積み下ろしのため、水上へ突き出して設けた橋状の施設。」という意味に最も近い語を選びなさい。","options":["主人公","桟橋","利息","旦那"],"answer":"桟橋","explanationKo":"「桟橋」의 핵심 의미는 잔교; 부두; 선착장이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-12','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4012","prompt":"「囲碁を打つための盤。」という意味に最も近い語を選びなさい。","options":["碁盤","観","油絵","縁側"],"answer":"碁盤","explanationKo":"「碁盤」의 핵심 의미는 바둑판이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-12','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4013","prompt":"「分数で横線の下にある数・式。」という意味に最も近い語を選びなさい。","options":["従業員","助け","張り紙","分母"],"answer":"分母","explanationKo":"「分母」의 핵심 의미는 분모이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-12','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4014","prompt":"「結婚について持ち上がる話・相談。」という意味に最も近い語を選びなさい。","options":["内部","登校","縁談","救い"],"answer":"縁談","explanationKo":"「縁談」의 핵심 의미는 혼담; 결혼 이야기이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-12','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4015","prompt":"「列車・バス・船などの発着時刻をまとめた表。」という意味に最も近い語を選びなさい。","options":["派遣","時刻表","読者","採用"],"answer":"時刻表","explanationKo":"「時刻表」의 핵심 의미는 시각표; 시간표; 운행 시간표이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-12','grammar',1,'〜なくもない','{"pattern":"〜なくもない","meaningKo":"전혀 〜하지 않은 것도 아니다","explanation":"〜なくもない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"見方によっては、彼の意見に賛成できなくもない。","ko":"문맥에서 전혀 〜하지 않은 것도 아니다의 의미로 쓰였다."},{"ja":"時間を延ばせば、今日中に完成できなくもない。","ko":"이 문장도 전혀 〜하지 않은 것도 아니다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-12','grammar',2,'〜ならともかく','{"pattern":"〜ならともかく","meaningKo":"〜라면 몰라도","explanation":"〜ならともかく는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"一度ならともかく、同じ失敗を三度も繰り返すのは問題だ。","ko":"문맥에서 〜라면 몰라도의 의미로 쓰였다."},{"ja":"専門家ならともかく、一般の利用者には難しい表現だ。","ko":"이 문장도 〜라면 몰라도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-12','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n見方によっては、彼の意見に賛成でき（　）。","options":["〜なくもない","〜にとどまる","〜を差し置いて","〜だけましだ"],"answer":"〜なくもない","explanationKo":"문맥상 전혀 〜하지 않은 것도 아니다를 나타내는 「〜なくもない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-12','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n一度（　）、同じ失敗を三度も繰り返すのは問題だ。","options":["〜は別として","〜あろうことか","〜だの〜だの","〜ならともかく"],"answer":"〜ならともかく","explanationKo":"문맥상 〜라면 몰라도를 나타내는 「〜ならともかく」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-12','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n外見（　）、機能面では十分に実用的だ。","options":["〜いざ〜となると","〜た拍子に","〜ならともあれ","〜までもなく"],"answer":"〜ならともあれ","explanationKo":"문맥상 〜라면 어쨌든; 〜는 차치하고를 나타내는 「〜ならともあれ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-12','reading',1,'採用基準の代理指標を疑う','{"passage":"応募者の能力を限られた情報から評価することには、多数の候補を一定の手順で比較できることという利点がある。ただし、学歴などの代理指標が職務能力と無関係な格差を持ち込むことには注意しなければならない。単一の数字や事例だけで結論を固定せず、前提と影響を継続して検証する必要がある。したがって、実際の業務に必要な能力を直接測る方法を組み合わせることが重要なのである。","questions":[{"prompt":"「採用基準の代理指標を疑う」について筆者が最も重視していることは何か。","options":["実際の業務に必要な能力を直接測る方法を組み合わせること","一つの数字だけで結論を固定すること","例外をすべて判断対象から外すこと","実施後の影響を確認しないこと"],"answer":"実際の業務に必要な能力を直接測る方法を組み合わせること","explanationKo":"본문에서는 実際の業務に必要な能力を直接測る方法を組み合わせること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["学歴などの代理指標が職務能力と無関係な格差を持ち込むこと","前提を示すと比較が不可能になること","記録を残すと利点が失われること","複数の資料を使うと判断できなくなること"],"answer":"学歴などの代理指標が職務能力と無関係な格差を持ち込むこと","explanationKo":"주의할 점은 学歴などの代理指標が職務能力と無関係な格差を持ち込むこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["多数の候補を一定の手順で比較できること","単一の事例だけで方針を決めるべきだ","実施後の検証は不要である","影響を受ける人の違いは考慮しなくてよい"],"answer":"多数の候補を一定の手順で比較できること","explanationKo":"応募者の能力を限られた情報から評価すること에는 多数の候補を一定の手順で比較できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-13','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4021","prompt":"「十字路」の読み方として最も適切なものを選びなさい。","options":["じゅうじろ","からだ","おくれ","しめきり"],"answer":"じゅうじろ","explanationKo":"「十字路」는 「じゅうじろ」라고 읽는다. 뜻은 사거리; 네거리이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
