INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-13','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-4024","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n事故の詳しい原因は依然として（　）のままだ。","options":["愚か","不明","明白","不良"],"answer":"不明","explanationKo":"문맥상 「不明」가 가장 자연스럽다. 불명; 불명확함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-13','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-4025","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）は三営業日以内に結果を通知しますが、繁忙期は遅れる場合があります。","options":["通常","受身","遥か","不良"],"answer":"通常","explanationKo":"문맥상 「通常」가 가장 자연스럽다. 통상; 보통; 일반적으로라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-13','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-4026","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n技術は（　）進歩しているため、継続して学ぶ姿勢が欠かせない。","options":["不明","洋風","明白","日々"],"answer":"日々","explanationKo":"문맥상 「日々」가 가장 자연스럽다. 나날; 매일매일라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-13','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-4027","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）で転職を考えるなら、希望条件だけでなく自分の強みも整理したほうがいい。","options":["受身","不良","本気","名高い"],"answer":"本気","explanationKo":"문맥상 「本気」가 가장 자연스럽다. 진심; 진지함; 본심라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-13','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-4028","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n検査工程で（　）品が見つかったため、同じ製造ロットをすべて確認した。","options":["受身","不良","愚か","名高い"],"answer":"不良","explanationKo":"문맥상 「不良」가 가장 자연스럽다. 불량; 좋지 않음; 결함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-13','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-4029","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n長時間集中力を（　）には、適度に休憩を取ることが重要だ。","options":["保つ","殴る","当てはめる","任す"],"answer":"保つ","explanationKo":"문맥상 「保つ」가 가장 자연스럽다. 유지하다; 보존하다; 지키다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-13','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-4030","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）な舞台の裏では、多くのスタッフが地道な準備を続けている。","options":["通常","上手","愚か","華やか"],"answer":"華やか","explanationKo":"문맥상 「華やか」가 가장 자연스럽다. 화려함; 눈부시고 밝음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-13','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4031","prompt":"「それほど時間が経たないうちに。すぐに。」という意味に最も近い語を選びなさい。","options":["不良","鮮やか","間もなく","眩しい"],"answer":"間もなく","explanationKo":"「間もなく」의 핵심 의미는 곧; 머지않아이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-13','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4032","prompt":"「優れた点・業績などによって、世間に広く名を知られている。」という意味に最も近い語を選びなさい。","options":["本気","名高い","洋風","平たい"],"answer":"名高い","explanationKo":"「名高い」의 핵심 의미는 이름난; 명성이 높은; 유명한이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-13','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4033","prompt":"「判断・答え・方法などが正しくない状態になる。また、誤った行動をする。」という意味に最も近い語を選びなさい。","options":["間違う","休める","受かる","引き下げる"],"answer":"間違う","explanationKo":"「間違う」의 핵심 의미는 틀리다; 잘못하다; 착각하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-13','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4034","prompt":"「人・車などが多く集まり、混雑する。」という意味に最も近い語を選びなさい。","options":["問い合わせる","粘る","丸める","混む"],"answer":"混む","explanationKo":"「混む」의 핵심 의미는 붐비다; 혼잡하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-13','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4035","prompt":"「表面が平らで広がっている。また、表現などが分かりやすく平易なさま。」という意味に最も近い語を選びなさい。","options":["爽やか","不明","平たい","詳細"],"answer":"平たい","explanationKo":"「平たい」의 핵심 의미는 납작하다; 평평하다; 쉬운 말로 풀어쓴이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-13','grammar',1,'〜ならともあれ','{"pattern":"〜ならともあれ","meaningKo":"〜라면 어쨌든; 〜는 차치하고","explanation":"〜ならともあれ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"結果ならともあれ、挑戦した経験には価値がある。","ko":"문맥에서 〜라면 어쨌든; 〜는 차치하고의 의미로 쓰였다."},{"ja":"外見ならともあれ、機能面では十分に実用的だ。","ko":"이 문장도 〜라면 어쨌든; 〜는 차치하고의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-13','grammar',2,'〜に値する','{"pattern":"〜に値する","meaningKo":"〜할 가치가 있다","explanation":"〜に値する는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"この報告書は慎重に検討するに値する。","ko":"문맥에서 〜할 가치가 있다의 의미로 쓰였다."},{"ja":"彼女の長年の貢献は高く評価するに値する。","ko":"이 문장도 〜할 가치가 있다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-13','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n結果（　）、挑戦した経験には価値がある。","options":["〜までもなく","〜いざ〜となると","〜た拍子に","〜ならともあれ"],"answer":"〜ならともあれ","explanationKo":"문맥상 〜라면 어쨌든; 〜는 차치하고를 나타내는 「〜ならともあれ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-13','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこの報告書は慎重に検討する（　）。","options":["〜かいもなく","〜てでも","〜に値する","〜も構わず"],"answer":"〜に値する","explanationKo":"문맥상 〜할 가치가 있다를 나타내는 「〜に値する」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-13','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n手順どおりに処理した結果なら、非難する（　）。","options":["〜てみせる","〜にあたらず","〜もそこそこに","〜かいがあって"],"answer":"〜にあたらず","explanationKo":"문맥상 〜할 필요가 없다를 나타내는 「〜にあたらず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-13','reading',1,'公開後の訂正経路を準備する','{"passage":"組織が情報を広く公開することには、多くの人が同じ情報を利用し判断できることという利点がある。ただし、誤りを恐れて公開を遅らせすぎるか訂正方法なしに急ぐことには注意しなければならない。単一の数字や事例だけで結論を固定せず、前提と影響を継続して検証する必要がある。したがって、版と更新履歴を示し速やかに訂正を伝えられるようにすることが重要なのである。","questions":[{"prompt":"「公開後の訂正経路を準備する」について筆者が最も重視していることは何か。","options":["版と更新履歴を示し速やかに訂正を伝えられるようにすること","一つの数字だけで結論を固定すること","例外をすべて判断対象から外すこと","実施後の影響を確認しないこと"],"answer":"版と更新履歴を示し速やかに訂正を伝えられるようにすること","explanationKo":"본문에서는 版と更新履歴を示し速やかに訂正を伝えられるようにすること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["誤りを恐れて公開を遅らせすぎるか訂正方法なしに急ぐこと","前提を示すと比較が不可能になること","記録を残すと利点が失われること","複数の資料を使うと判断できなくなること"],"answer":"誤りを恐れて公開を遅らせすぎるか訂正方法なしに急ぐこと","explanationKo":"주의할 점은 誤りを恐れて公開を遅らせすぎるか訂正方法なしに急ぐこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["多くの人が同じ情報を利用し判断できること","単一の事例だけで方針を決めるべきだ","実施後の検証は不要である","影響を受ける人の違いは考慮しなくてよい"],"answer":"多くの人が同じ情報を利用し判断できること","explanationKo":"組織が情報を広く公開すること에는 多くの人が同じ情報を利用し判断できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-14','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4041","prompt":"「怒り」の読み方として最も適切なものを選びなさい。","options":["かがい","いかり","きげき","ひなた"],"answer":"いかり","explanationKo":"「怒り」는 「いかり」라고 읽는다. 뜻은 분노; 화이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-14','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4042","prompt":"「遅れ」の読み方として最も適切なものを選びなさい。","options":["おくれ","けっしょう","はちみつ","からだ"],"answer":"おくれ","explanationKo":"「遅れ」는 「おくれ」라고 읽는다. 뜻은 지연; 늦음; 뒤처짐이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-14','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4043","prompt":"「助け」の読み方として最も適切なものを選びなさい。","options":["あとまわし","こうしんりょう","たのみ","たすけ"],"answer":"たすけ","explanationKo":"「助け」는 「たすけ」라고 읽는다. 뜻은 도움; 구원이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-14','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-4044","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n医師の（　）で、毎日少しずつ運動する習慣を始めた。","options":["文書","英雄","勧め","悩み"],"answer":"勧め","explanationKo":"문맥상 「勧め」가 가장 자연스럽다. 권유; 추천라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
