INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-14','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-4046","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n発表の（　）では、今後の課題と展望を簡潔にまとめた。","options":["結び","提供","固定","体"],"answer":"結び","explanationKo":"문맥상 「結び」가 가장 자연스럽다. 맺음; 결론; 매듭라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-14','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-4047","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n大雨が続くと河川が氾濫する（　）があるため、早めの避難が必要だ。","options":["黄色","月日","定食","恐れ"],"answer":"恐れ","explanationKo":"문맥상 「恐れ」가 가장 자연스럽다. 두려움; 우려; 가능성라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-14','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-4048","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n今年の降水量は例年（　）だが、地域による差が大きい。","options":["元年","教職","並み","劇団"],"answer":"並み","explanationKo":"문맥상 「並み」가 가장 자연스럽다. 보통 수준; ~와 같은 정도라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-14','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-4049","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nその契約に署名した（　）がないため、記録を確認してほしい。","options":["使い道","覚え","天国","共学"],"answer":"覚え","explanationKo":"문맥상 「覚え」가 가장 자연스럽다. 기억; 기억하고 있음; 익힌 정도라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-14','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-4050","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n本人確認のため、身分証明書の（　）を提出してください。","options":["写し","左利き","三味線","叫び"],"answer":"写し","explanationKo":"문맥상 「写し」가 가장 자연스럽다. 사본; 복사본라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-14','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4051","prompt":"「他人の苦しみ・事情を思いやる心。人情や慈悲。」という意味に最も近い語を選びなさい。","options":["申し込み","保険","乗客","情け"],"answer":"情け","explanationKo":"「情け」의 핵심 의미는 인정; 자비; 연민이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-14','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4052","prompt":"「参加・契約・利用などを希望して、必要な手続きをすること。」という意味に最も近い語を選びなさい。","options":["水洗","勝利","申し込み","現地"],"answer":"申し込み","explanationKo":"「申し込み」의 핵심 의미는 신청; 접수이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-14','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4053","prompt":"「解決できず心を苦しめている問題・心配。」という意味に最も近い語を選びなさい。","options":["上下","悩み","保護","手配"],"answer":"悩み","explanationKo":"「悩み」의 핵심 의미는 고민; 걱정거리이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-14','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4054","prompt":"「予想外のことに接して強くびっくりすること。また、その感情。」という意味に最も近い語を選びなさい。","options":["驚き","聖書","利子","本館"],"answer":"驚き","explanationKo":"「驚き」의 핵심 의미는 놀람; 놀라움이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-14','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4055","prompt":"「大声で叫ぶこと。また、強い感情・要求を表す声や訴え。」という意味に最も近い語を選びなさい。","options":["学芸","風車","用法","叫び"],"answer":"叫び","explanationKo":"「叫び」의 핵심 의미는 외침; 고함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-14','grammar',1,'〜にあたらず','{"pattern":"〜にあたらず","meaningKo":"〜할 필요가 없다","explanation":"〜にあたらず는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"予想の範囲内であり、驚くにあたらず。","ko":"문맥에서 〜할 필요가 없다의 의미로 쓰였다."},{"ja":"手順どおりに処理した結果なら、非難するにあたらず。","ko":"이 문장도 〜할 필요가 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-14','grammar',2,'〜にとどまる','{"pattern":"〜にとどまる","meaningKo":"〜에 그치다","explanation":"〜にとどまる는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"今回の変更は名称の修正にとどまる。","ko":"문맥에서 〜에 그치다의 의미로 쓰였다."},{"ja":"被害は倉庫の一部にとどまり、人的被害はなかった。","ko":"이 문장도 〜에 그치다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-14','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n予想の範囲内であり、驚く（　）。","options":["〜かいがあって","〜てみせる","〜にあたらず","〜もそこそこに"],"answer":"〜にあたらず","explanationKo":"문맥상 〜할 필요가 없다를 나타내는 「〜にあたらず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-14','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n今回の変更は名称の修正（　）。","options":["〜とあってか","〜にとどまる","〜ようでは","〜かぎりを尽くす"],"answer":"〜にとどまる","explanationKo":"문맥상 〜에 그치다를 나타내는 「〜にとどまる」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-14','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n結果（　）、検証の過程は適切だった。","options":["〜は別として","〜を差し置いて","〜がましい","〜とでもいうべき"],"answer":"〜は別として","explanationKo":"문맥상 〜은 별개로 하고를 나타내는 「〜は別として」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-14','reading',1,'体験談と代表性を区別する','{"passage":"当事者の具体的な経験を政策議論に生かすことには、統計だけでは分からない過程や負担を理解できることという利点がある。ただし、印象的な一例を集団全体の傾向とみなすことには注意しなければならない。単一の数字や事例だけで結論を固定せず、前提と影響を継続して検証する必要がある。したがって、体験の文脈を保ちながら他の資料と照合することが重要なのである。","questions":[{"prompt":"「体験談と代表性を区別する」について筆者が最も重視していることは何か。","options":["体験の文脈を保ちながら他の資料と照合すること","一つの数字だけで結論を固定すること","例外をすべて判断対象から外すこと","実施後の影響を確認しないこと"],"answer":"体験の文脈を保ちながら他の資料と照合すること","explanationKo":"본문에서는 体験の文脈を保ちながら他の資料と照合すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["印象的な一例を集団全体の傾向とみなすこと","前提を示すと比較が不可能になること","記録を残すと利点が失われること","複数の資料を使うと判断できなくなること"],"answer":"印象的な一例を集団全体の傾向とみなすこと","explanationKo":"주의할 점은 印象的な一例を集団全体の傾向とみなすこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["統計だけでは分からない過程や負担を理解できること","単一の事例だけで方針を決めるべきだ","実施後の検証は不要である","影響を受ける人の違いは考慮しなくてよい"],"answer":"統計だけでは分からない過程や負担を理解できること","explanationKo":"当事者の具体的な経験を政策議論に生かすこと에는 統計だけでは分からない過程や負担を理解できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-15','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4061","prompt":"「共働き」の読み方として最も適切なものを選びなさい。","options":["とうろく","あいたい","ともばたらき","かいはつ"],"answer":"ともばたらき","explanationKo":"「共働き」는 「ともばたらき」라고 읽는다. 뜻은 맞벌이이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-15','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4062","prompt":"「夕暮れ」の読み方として最も適切なものを選びなさい。","options":["きげき","ゆうぐれ","こうりつ","こぜに"],"answer":"ゆうぐれ","explanationKo":"「夕暮れ」는 「ゆうぐれ」라고 읽는다. 뜻은 해질녘; 황혼이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
