INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-15','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-4064","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n希少な動植物を（　）するため、この地域への立ち入りが制限されている。","options":["慣れ","期末","作物","保護"],"answer":"保護","explanationKo":"문맥상 「保護」가 가장 자연스럽다. 보호라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
