INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-15','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-4067","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n警察は（　）事件として捜査を進め、目撃情報を集めている。","options":["殺人","貴族","喫茶","提供"],"answer":"殺人","explanationKo":"문맥상 「殺人」가 가장 자연스럽다. 살인라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-15','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-4068","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n捜査員は（　）に残されたわずかな痕跡を慎重に調べた。","options":["冬眠","予想","黄色","現場"],"answer":"現場","explanationKo":"문맥상 「現場」가 가장 자연스럽다. 현장; 사건 현장라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-15','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-4069","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n今回の（　）では若年層の投票率が大きな焦点となっている。","options":["値引き","開催","選挙","登校"],"answer":"選挙","explanationKo":"문맥상 「選挙」가 가장 자연스럽다. 선거라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-15','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-4070","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）の利益だけでなく、社会全体への影響も考える必要がある。","options":["天国","自己","晴天","一目"],"answer":"自己","explanationKo":"문맥상 「自己」가 가장 자연스럽다. 자기; 자신라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-15','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4071","prompt":"「事業や活動など、特定の目的のために用いる金銭。」という意味に最も近い語を選びなさい。","options":["資金","大空","漁村","左利き"],"answer":"資金","explanationKo":"「資金」의 핵심 의미는 자금이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
