INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-15','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4073","prompt":"「事故・病気・災害などに備え、一定の負担と引き換えに補償を受ける制度。」という意味に最も近い語を選びなさい。","options":["現場","現地","保険","並み"],"answer":"保険","explanationKo":"「保険」의 핵심 의미는 보험이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
