INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-15','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4075","prompt":"「将来の利益や成果を期待して、資金・時間・労力などを投入すること。」という意味に最も近い語を選びなさい。","options":["投資","夕暮れ","一言","合唱"],"answer":"投資","explanationKo":"「投資」의 핵심 의미는 투자이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-15','grammar',1,'〜は別として','{"pattern":"〜は別として","meaningKo":"〜은 별개로 하고","explanation":"〜は別として는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"費用の問題は別として、この案には技術的な課題がある。","ko":"문맥에서 〜은 별개로 하고의 의미로 쓰였다."},{"ja":"結果は別として、検証の過程は適切だった。","ko":"이 문장도 〜은 별개로 하고의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-15','grammar',2,'〜までもなく','{"pattern":"〜までもなく","meaningKo":"〜할 것도 없이","explanation":"〜までもなく는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"言うまでもなく、安全は速度より優先される。","ko":"문맥에서 〜할 것도 없이의 의미로 쓰였다."},{"ja":"改めて確認するまでもなく、記録に明記されている。","ko":"이 문장도 〜할 것도 없이의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-15','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n費用の問題（　）、この案には技術的な課題がある。","options":["〜とでもいうべき","〜は別として","〜を差し置いて","〜がましい"],"answer":"〜は別として","explanationKo":"문맥상 〜은 별개로 하고를 나타내는 「〜は別として」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-15','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n言う（　）、安全は速度より優先される。","options":["〜までもなく","〜あろうことか","〜ぐるみ","〜ないとも限らない"],"answer":"〜までもなく","explanationKo":"문맥상 〜할 것도 없이를 나타내는 「〜までもなく」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-15','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n周囲の視線（　）、大声で助けを求めた。","options":["〜いざ〜となると","〜だけましだ","〜なくはない","〜も構わず"],"answer":"〜も構わず","explanationKo":"문맥상 〜도 아랑곳하지 않고를 나타내는 「〜も構わず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-15','reading',1,'予想が行動を変える循環','{"passage":"将来の需要や危険を予測して公表することには、早めの準備と資源配分を促せることという利点がある。ただし、公表された予想によって人々の行動が変わり結果も変化することには注意しなければならない。単一の数字や事例だけで結論を固定せず、前提と影響を継続して検証する必要がある。したがって、予想値だけでなく前提と行動変化の可能性を説明することが重要なのである。","questions":[{"prompt":"「予想が行動を変える循環」について筆者が最も重視していることは何か。","options":["予想値だけでなく前提と行動変化の可能性を説明すること","一つの数字だけで結論を固定すること","例外をすべて判断対象から外すこと","実施後の影響を確認しないこと"],"answer":"予想値だけでなく前提と行動変化の可能性を説明すること","explanationKo":"본문에서는 予想値だけでなく前提と行動変化の可能性を説明すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["公表された予想によって人々の行動が変わり結果も変化すること","前提を示すと比較が不可能になること","記録を残すと利点が失われること","複数の資料を使うと判断できなくなること"],"answer":"公表された予想によって人々の行動が変わり結果も変化すること","explanationKo":"주의할 점은 公表された予想によって人々の行動が変わり結果も変化すること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["早めの準備と資源配分を促せること","単一の事例だけで方針を決めるべきだ","実施後の検証は不要である","影響を受ける人の違いは考慮しなくてよい"],"answer":"早めの準備と資源配分を促せること","explanationKo":"将来の需要や危険を予測して公表すること에는 早めの準備と資源配分を促せること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-16','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4081","prompt":"「派遣」の読み方として最も適切なものを選びなさい。","options":["ねんごう","かいがら","じこくひょう","はけん"],"answer":"はけん","explanationKo":"「派遣」는 「はけん」라고 읽는다. 뜻은 파견; 파송이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-16','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4082","prompt":"「同意」の読み方として最も適切なものを選びなさい。","options":["おそれ","さつじん","どうい","ごばん"],"answer":"どうい","explanationKo":"「同意」는 「どうい」라고 읽는다. 뜻은 동의이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-16','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4083","prompt":"「公開」の読み方として最も適切なものを選びなさい。","options":["にゅうよく","こうかい","ともばたらき","どうし"],"answer":"こうかい","explanationKo":"「公開」는 「こうかい」라고 읽는다. 뜻은 공개이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-16','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-4084","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n祭りの運営には（　）の住民や商店が毎年協力している。","options":["地元","出演","慣れ","期末"],"answer":"地元","explanationKo":"문맥상 「地元」가 가장 자연스럽다. 고장; 지역; 현지라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-16','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-4085","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n事故防止のため、駅のホームに新しい安全柵が（　）された。","options":["設定","後悔","慣れ","設置"],"answer":"設置","explanationKo":"문맥상 「設置」가 가장 자연스럽다. 설치라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-16','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-4086","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n新商品の発表に対する消費者の（　）は予想以上に好意的だった。","options":["正解","式場","反応","道場"],"answer":"反応","explanationKo":"문맥상 「反応」가 가장 자연스럽다. 반응라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-16','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-4087","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n発掘調査によって、この地域に（　）の集落が存在したことが分かった。","options":["覚え","古代","三日月","縁談"],"answer":"古代","explanationKo":"문맥상 「古代」가 가장 자연스럽다. 고대라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-16','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-4088","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n高額な機器を（　）する前に、複数の製品を比較して性能を確認した。","options":["購入","極楽","三日月","縁談"],"answer":"購入","explanationKo":"문맥상 「購入」가 가장 자연스럽다. 구입; 구매라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-16','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-4089","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n国際会議は来年五月に東京で（　）される予定だ。","options":["桟橋","結び","施設","開催"],"answer":"開催","explanationKo":"문맥상 「開催」가 가장 자연스럽다. 개최라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-16','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-4090","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n調査委員会は事故原因だけでなく、組織（　）の管理体制も検証した。","options":["反応","歯科","内部","値引き"],"answer":"内部","explanationKo":"문맥상 「内部」가 가장 자연스럽다. 내부; 안쪽; 조직 내부라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-16','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4091","prompt":"「将来起こることや結果について、前もって見当をつけること。」という意味に最も近い語を選びなさい。","options":["同意","予想","読者","専用"],"answer":"予想","explanationKo":"「予想」의 핵심 의미는 예상; 예측이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-16','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4092","prompt":"「氏名や情報などを所定の帳簿・名簿・システムに記載して正式に扱える状態にすること。」という意味に最も近い語を選びなさい。","options":["登録","参照","出演","宛"],"answer":"登録","explanationKo":"「登録」의 핵심 의미는 등록이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-16','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4093","prompt":"「昔から人々の間で語り伝えられてきた話。」という意味に最も近い語を選びなさい。","options":["裸足","特技","一部分","伝説"],"answer":"伝説","explanationKo":"「伝説」의 핵심 의미는 전설이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-16','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4094","prompt":"「軍隊・兵器・戦争など、軍に関する事柄。」という意味に最も近い語を選びなさい。","options":["分母","並み","軍事","熱湯"],"answer":"軍事","explanationKo":"「軍事」의 핵심 의미는 군사이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-16','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4095","prompt":"「必要な人・物・手段などを前もって準備したり取り決めたりすること。また、警察が容疑者などを捜して逮捕できるよう関係先に連絡すること。」という意味に最も近い語を選びなさい。","options":["分母","手配","主人公","熱湯"],"answer":"手配","explanationKo":"「手配」의 핵심 의미는 수배; 준비; 주선이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-16','grammar',1,'〜も構わず','{"pattern":"〜も構わず","meaningKo":"〜도 아랑곳하지 않고","explanation":"〜も構わず는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"雨にぬれるのも構わず、彼は現場へ走った。","ko":"문맥에서 〜도 아랑곳하지 않고의 의미로 쓰였다."},{"ja":"周囲の視線も構わず、大声で助けを求めた。","ko":"이 문장도 〜도 아랑곳하지 않고의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-16','grammar',2,'〜もそこそこに','{"pattern":"〜もそこそこに","meaningKo":"〜도 대충 마치고","explanation":"〜もそこそこに는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"食事もそこそこに、急いで会社へ戻った。","ko":"문맥에서 〜도 대충 마치고의 의미로 쓰였다."},{"ja":"挨拶もそこそこに、担当者は本題に入った。","ko":"이 문장도 〜도 대충 마치고의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-16','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n雨にぬれるの（　）、彼は現場へ走った。","options":["〜も構わず","〜いざ〜となると","〜だけましだ","〜なくはない"],"answer":"〜も構わず","explanationKo":"문맥상 〜도 아랑곳하지 않고를 나타내는 「〜も構わず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-16','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n食事（　）、急いで会社へ戻った。","options":["〜かいもなく","〜だの〜だの","〜なくもない","〜もそこそこに"],"answer":"〜もそこそこに","explanationKo":"문맥상 〜도 대충 마치고를 나타내는 「〜もそこそこに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-16','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n説明のたびに内容が変わる（　）、信頼を得られない。","options":["〜た拍子に","〜ならともかく","〜ようでは","〜かいがあって"],"answer":"〜ようでは","explanationKo":"문맥상 〜하는 상태라면를 나타내는 「〜ようでは」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-16','reading',1,'無線通信の予備経路を試す','{"passage":"災害時に複数の通信手段を備えることには、一つの回線が止まっても情報を届けられることという利点がある。ただし、機器を保管するだけでは操作方法や電源の問題に気づけないことには注意しなければならない。単一の数字や事例だけで結論を固定せず、前提と影響を継続して検証する必要がある。したがって、異なる条件で定期的に接続と運用を訓練することが重要なのである。","questions":[{"prompt":"「無線通信の予備経路を試す」について筆者が最も重視していることは何か。","options":["異なる条件で定期的に接続と運用を訓練すること","一つの数字だけで結論を固定すること","例外をすべて判断対象から外すこと","実施後の影響を確認しないこと"],"answer":"異なる条件で定期的に接続と運用を訓練すること","explanationKo":"본문에서는 異なる条件で定期的に接続と運用を訓練すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["機器を保管するだけでは操作方法や電源の問題に気づけないこと","前提を示すと比較が不可能になること","記録を残すと利点が失われること","複数の資料を使うと判断できなくなること"],"answer":"機器を保管するだけでは操作方法や電源の問題に気づけないこと","explanationKo":"주의할 점은 機器を保管するだけでは操作方法や電源の問題に気づけないこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["一つの回線が止まっても情報を届けられること","単一の事例だけで方針を決めるべきだ","実施後の検証は不要である","影響を受ける人の違いは考慮しなくてよい"],"answer":"一つの回線が止まっても情報を届けられること","explanationKo":"災害時に複数の通信手段を備えること에는 一つの回線が止まっても情報を届けられること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-17','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4101","prompt":"「一言」の読み方として最も適切なものを選びなさい。","options":["いちげん","いえぬし","ねんごう","かいがら"],"answer":"いちげん","explanationKo":"「一言」는 「いちげん」라고 읽는다. 뜻은 한마디; 한마디 말이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-17','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4102","prompt":"「部下」の読み方として最も適切なものを選びなさい。","options":["おおみず","ごばん","おそれ","ぶか"],"answer":"ぶか","explanationKo":"「部下」는 「ぶか」라고 읽는다. 뜻은 부하; 하급 직원이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-17','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4103","prompt":"「地獄」の読み方として最も適切なものを選びなさい。","options":["ともばたらき","ぶか","じごく","すすめ"],"answer":"じごく","explanationKo":"「地獄」는 「じごく」라고 읽는다. 뜻은 지옥; 극도로 괴로운 상태이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-17','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-4104","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n避難訓練では、（　）が利用者を安全な場所まで誘導した。","options":["無駄遣い","職員","伝説","宛"],"answer":"職員","explanationKo":"문맥상 「職員」가 가장 자연스럽다. 직원; 교직원·공무원 등의 직원라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-17','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-4105","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n申請書に記入漏れの（　）が二つあるので、提出前に修正してください。","options":["箇所","地元","一言","天井"],"answer":"箇所","explanationKo":"문맥상 「箇所」가 가장 자연스럽다. 곳; 부분; 개소라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-17','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-4106","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの城はかつて有力な（　）の住居として使われていた。","options":["了解","災害","問屋","貴族"],"answer":"貴族","explanationKo":"문맥상 「貴族」가 가장 자연스럽다. 귀족라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-17','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-4107","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n判断に迷ったため、まず（　）に状況を報告して指示を仰いだ。","options":["主食","真上","上司","音色"],"answer":"上司","explanationKo":"문맥상 「上司」가 가장 자연스럽다. 상사라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-17','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-4108","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n日程変更の件は（　）しました。関係者にもこちらから連絡します。","options":["主食","了解","格","音色"],"answer":"了解","explanationKo":"문맥상 「了解」가 가장 자연스럽다. 이해; 승낙; 알겠음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-17','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-4109","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n正確な被害状況を確認するため、調査員を（　）に派遣した。","options":["現地","短波","桟橋","結び"],"answer":"現地","explanationKo":"문맥상 「現地」가 가장 자연스럽다. 현지; 현장 지역라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-17','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-4110","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は（　）と評されたが、その成果の裏には長年の地道な努力もあった。","options":["助け","張り紙","一言","天才"],"answer":"天才","explanationKo":"문맥상 「天才」가 가장 자연스럽다. 천재라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-17','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4111","prompt":"「燃焼などによって熱や動力などのエネルギーを得るために使う物質。」という意味に最も近い語を選びなさい。","options":["入浴","値引き","燃料","内部"],"answer":"燃料","explanationKo":"「燃料」의 핵심 의미는 연료이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-17','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4112","prompt":"「困難な課題や相手に対して、成功や勝利を目指して立ち向かうこと。」という意味に最も近い語を選びなさい。","options":["読者","挑戦","救い","古代"],"answer":"挑戦","explanationKo":"「挑戦」의 핵심 의미는 도전이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-17','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4113","prompt":"「人が特定の相手に恋愛感情を抱き、互いに愛情を深めたり交際したりすること。」という意味に最も近い語を選びなさい。","options":["恋愛","燃料","微笑","参照"],"answer":"恋愛","explanationKo":"「恋愛」의 핵심 의미는 연애; 사랑이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-17','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4114","prompt":"「映画・舞台・テレビ・ラジオなどに出て、演技・演奏・発言などをすること。」という意味に最も近い語を選びなさい。","options":["勝利","指示","災害","出演"],"answer":"出演","explanationKo":"「出演」의 핵심 의미는 출연이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-17','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4115","prompt":"「過去にしたことやしなかったことを振り返り、誤りだった、または別の選択をすべきだったと悔やむこと。」という意味に最も近い語を選びなさい。","options":["神殿","本場","後悔","暦"],"answer":"後悔","explanationKo":"「後悔」의 핵심 의미는 후회이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-17','grammar',1,'〜ようでは','{"pattern":"〜ようでは","meaningKo":"〜하는 상태라면","explanation":"〜ようでは는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"基本的な記録さえ残せないようでは、改善は望めない。","ko":"문맥에서 〜하는 상태라면의 의미로 쓰였다."},{"ja":"説明のたびに内容が変わるようでは、信頼を得られない。","ko":"이 문장도 〜하는 상태라면의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-17','grammar',2,'〜を差し置いて','{"pattern":"〜を差し置いて","meaningKo":"〜을 제쳐 두고","explanation":"〜を差し置いて는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"責任者を差し置いて、私が決定することはできない。","ko":"문맥에서 〜을 제쳐 두고의 의미로 쓰였다."},{"ja":"緊急課題を差し置いて、別の作業を始めるべきではない。","ko":"이 문장도 〜을 제쳐 두고의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-17','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n基本的な記録さえ残せない（　）、改善は望めない。","options":["〜かいがあって","〜た拍子に","〜ならともかく","〜ようでは"],"answer":"〜ようでは","explanationKo":"문맥상 〜하는 상태라면를 나타내는 「〜ようでは」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-17','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n責任者（　）、私が決定することはできない。","options":["〜てでも","〜ならともあれ","〜を差し置いて","〜かぎりを尽くす"],"answer":"〜を差し置いて","explanationKo":"문맥상 〜을 제쳐 두고를 나타내는 「〜を差し置いて」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-17','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n（　）、警備員が鍵を持たずに巡回していた。","options":["〜に値する","〜あろうことか","〜がましい","〜てみせる"],"answer":"〜あろうことか","explanationKo":"문맥상 놀랍게도; 있을 수 있게도를 나타내는 「〜あろうことか」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-17','reading',1,'日々の小さな不良を共有する','{"passage":"重大事故に至らなかった異常を記録することには、大きな故障の兆候を早く発見できることという利点がある。ただし、報告者を責める文化では情報が組織内に上がらないことには注意しなければならない。単一の数字や事例だけで結論を固定せず、前提と影響を継続して検証する必要がある。したがって、個人の処罰より仕組みの改善に使う目的を明確にすることが重要なのである。","questions":[{"prompt":"「日々の小さな不良を共有する」について筆者が最も重視していることは何か。","options":["個人の処罰より仕組みの改善に使う目的を明確にすること","一つの数字だけで結論を固定すること","例外をすべて判断対象から外すこと","実施後の影響を確認しないこと"],"answer":"個人の処罰より仕組みの改善に使う目的を明確にすること","explanationKo":"본문에서는 個人の処罰より仕組みの改善に使う目的を明確にすること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["報告者を責める文化では情報が組織内に上がらないこと","前提を示すと比較が不可能になること","記録を残すと利点が失われること","複数の資料を使うと判断できなくなること"],"answer":"報告者を責める文化では情報が組織内に上がらないこと","explanationKo":"주의할 점은 報告者を責める文化では情報が組織内に上がらないこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["大きな故障の兆候を早く発見できること","単一の事例だけで方針を決めるべきだ","実施後の検証は不要である","影響を受ける人の違いは考慮しなくてよい"],"answer":"大きな故障の兆候を早く発見できること","explanationKo":"重大事故に至らなかった異常を記録すること에는 大きな故障の兆候を早く発見できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
